window.EXPL={"공인노2017_26-76-1":{"f":"보건복지부장관은 사회보장급여 관련 업무에 공통적으로 적용되는 기준을 마련할 수 있다.","w":"사회보장급여 관련 업무의 공통 기준은 사회보장위원회가 아니라 보건복지부장관이 마련하며, 마련 여부도 재량이다(사회보장기본법 제26조 제5항).","c":"상","v":1},"공인노2017_26-76-2":{"f":"사회보장 비용의 부담은 각각의 사회보장제도의 목적에 따라 국가, 지방자치단체 및 민간부문 간에 합리적으로 조정되어야 한다.","w":"사회보장기본법 제28조 제1항은 국가·지방자치단체가 먼저 부담하라고 하지 않고, 국가·지방자치단체·민간부문 사이에서 합리적으로 조정하라고 정한다.","c":"상","v":1},"공인노2017_26-76-4":{"f":"사회보험에 드는 비용은 사용자, 피용자 및 자영업자가 부담하는 것을 원칙으로 하되, 관계 법령에서 정하는 바에 따라 국가가 그 비용의 일부를 부담할 수 있다.","w":"사회보험 비용은 사용자·피용자·자영업자가 부담하는 것이 원칙이고 국가는 그 일부를 부담할 수 있다(사회보장기본법 제28조 제2항). 수익자 부담 원칙은 부담 능력이 있는 국민에 대한 사회서비스 비용에 적용된다.","c":"상","v":1},"공인노2017_26-76-5":{"f":"사회보장에 관한 기본계획은 다른 법령에 따라 수립되는 사회보장에 관한 계획에 우선하며 그 계획의 기본이 된다.","w":"기본계획은 다른 법령에 따른 사회보장 계획을 빼는 것이 아니라, 그 계획들보다 우선하고 그 계획들의 기본이 된다(사회보장기본법 제17조).","c":"상","v":1},"공인노2017_26-77-5":{"f":"사회보장수급권의 포기는 취소할 수 있다.","w":"사회보장수급권을 포기했더라도 그 포기는 취소할 수 있다(사회보장기본법 제14조 제2항).","c":"상","v":1},"공인노2019_28-76-1":{"f":"사회보험은 국가의 책임으로 시행하고, 공공부조와 사회서비스는 국가와 지방자치단체의 책임으로 시행하는 것을 원칙으로 한다.","w":"사회보험은 국가가 책임지고, 공공부조와 사회서비스는 국가와 지방자치단체가 함께 책임지는 것이 원칙이다(사회보장기본법 제25조 제5항).","c":"상","v":1},"공인노2019_28-77-4":{"f":"공공부조에 드는 비용의 전부 또는 일부는 국가와 지방자치단체가 부담한다.","w":"공공부조 비용은 수익자가 아니라 국가와 지방자치단체가 그 전부 또는 일부를 부담한다(사회보장기본법 제28조 제3항). 수익자 부담 원칙은 부담 능력이 있는 국민에 대한 사회서비스 비용에 적용된다(같은 조 제4항).","c":"상","v":1},"공인노2019_28-79-4":{"f":"사회보장수급권은 포기할 수 있고 포기한 후에도 이를 취소할 수 있다.","w":"수급권 포기는 정당한 권한이 있는 기관에 서면으로 통지해서 할 수 있고, 포기한 뒤에도 취소할 수 있다(사회보장기본법 제14조).","c":"상","v":1},"공인노2022_31-76-4":{"f":"국내에 거주하는 외국인에게 사회보장제도를 적용할 때에는 상호주의의 원칙에 따르되, 관계 법령에서 정하는 바에 따른다.","w":"외국인에게는 상호주의가 원칙이고, 구체적인 적용은 관계 법령에 따른다(사회보장기본법 제8조). 국민과 똑같이 대하는 것이 원칙이라는 규정은 없다.","c":"상","v":1},"공인노2022_31-77-3":{"f":"사회보험은 국가의 책임으로 시행하고, 공공부조와 사회서비스는 국가와 지방자치 단체의 책임으로 시행하는 것을 원칙으로 한다.","w":"국가 단독 책임인 것은 사회보험이고, 공공부조와 사회서비스는 국가와 지방자치단체가 함께 책임진다(사회보장기본법 제25조 제5항).","c":"상","v":1},"공인노2022_31-79-4":{"f":"사회보장수급권은 정당한 권한이 있는 기관에 서면으로 통지하여 포기할 수 있다.","w":"수급권 포기 통지는 서면으로만 할 수 있고 구두 통지는 인정되지 않는다(사회보장기본법 제14조 제1항).","c":"상","v":1},"공인노2024_33-42-1":{"f":"보건복지부장관은 사회보장 행정데이터 분석센터의 설치ㆍ운영에 관한 사무를 수행하기 위하여 불가피한 경우「개인정보 보호법」제23조에 따른 건강에 관한 정보가 포함된 자료를 처리할 수 있다.","w":"행정데이터 분석센터 사무에서 처리할 수 있는 자료는 건강에 관한 정보가 포함된 자료뿐이다. 범죄경력자료와 주민등록번호 등 고유식별정보는 사회보장정보시스템 구축·운영 사무에서 처리할 수 있는 자료다(사회보장기본법 시행령 제21조 제1항 제1호·제2호).","c":"상","v":1},"공인노2024_33-43-2":{"f":"보건복지부장관은 사회보장 재정추계를 위하여 재정추계를 실시하는 해의 6월 30일까지 재정추계 세부지침을 마련하여야 한다.","w":"재정추계 세부지침은 추계를 실시하는 해의 6월 30일까지 마련한다(사회보장기본법 시행령 제16조의3 제1항). 1월 31일은 시행계획 추진실적 평가지침을 통보하는 기한이다(같은 영 제6조 제1항).","c":"상","v":1},"공인노2025_34-41-1":{"f":"보건복지부장관은 관계 중앙행정기관의 장과 협의하여 기본계획을 5년마다 수립하여야 한다.","w":"사회보장 기본계획은 5년마다 수립한다(사회보장기본법 제16조 제1항).","c":"상","v":1},"공인노2025_34-42-1":{"f":"위원회의 위원장은 국무총리가 된다.","w":"사회보장위원회 위원장은 국무총리이고, 보건복지부장관은 부위원장 중 한 명이다(사회보장기본법 제21조).","c":"상","v":1},"공인노2025_34-42-2":{"f":"공무원인 위원의 임기는 그 재임기간으로 한다.","w":"위촉된 위원의 임기는 2년이고, 공무원인 위원은 그 직에 있는 동안(재임기간)만 위원이 된다(사회보장기본법 제21조).","c":"상","v":1},"공인노2025_34-42-3":{"f":"위원회에 실무위원회를 두며, 실무위원회에 간사 1명을 둔다.","w":"실무위원회의 간사는 1명이고, 고위공무원단에 속하는 일반직공무원 중에서 보건복지부장관이 지명한다(사회보장기본법 시행령 제11조 제7항). 간사 2명을 두는 곳은 사회보장위원회다(같은 영 제9조 제2항).","c":"상","v":1},"공인노2025_34-42-4":{"f":"위원회는 위원장 1명, 부위원장 3명을 포함한 30명 이내의 위원으로 구성한다.","w":"사회보장위원회는 위원장 1명과 부위원장 3명을 포함해 30명 이내로 구성한다(사회보장기본법 제21조 제1항). 부위원장은 교육부장관·보건복지부장관·기획예산처장관이다(같은 조 제2항).","c":"상","v":1},"공인노2025_34-43-3":{"f":"지방자치단체의 장이 사회보장제도를 신설하려는 경우 매년 6월 30일까지 협의요청서를 보건복지부장관에게 제출해야 한다.","w":"협의요청서 제출 기한은 중앙행정기관의 장은 매년 4월 30일, 지방자치단체의 장은 6월 30일이다(사회보장기본법 시행령 제15조 제1항).","c":"상","v":1},"공인노2026_35-41-1":{"f":"사회보장수급권의 포기는 취소할 수 있다.","w":"포기한 사회보장수급권도 그 포기를 취소할 수 있다(사회보장기본법 제14조 제2항).","c":"상","v":1},"공인노2026_35-41-2":{"f":"“사회보험”이란 국민에게 발생하는 사회적 위험을 보험의 방식으로 대처함으로써 국민의 건강과 소득을 보장하는 제도를 말한다.","w":"보험 방식으로 사회적 위험에 대처하는 제도는 사회보험의 정의다(사회보장기본법 제3조 제2호). 사회보장은 사회보험·공공부조·사회서비스를 모두 아우르는 말이다.","c":"상","v":1},"공인노2026_35-41-3":{"f":"“평생사회안전망”이란 생애주기에 걸쳐 보편적으로 충족되어야 하는 기본욕구와 특정한 사회위험에 의하여 발생하는 특수욕구를 동시에 고려하여 소득ㆍ서비스를 보장하는 맞춤형 사회보장제도를 말한다.","w":"기본욕구와 특수욕구를 함께 고려해 소득·서비스를 보장하는 맞춤형 제도는 평생사회안전망의 정의다(사회보장기본법 제3조 제5호). 사회서비스는 상담·재활·돌봄·정보 제공 등으로 삶의 질 향상을 지원하는 제도를 말한다.","c":"상","v":1},"공인노2026_35-41-5":{"f":"사회보험에 드는 비용은 사용자, 피용자 및 자영업자가 부담하는 것을 원칙으로 하되, 국가가 그 비용의 일부를 부담할 수 있다.","w":"사회보험 비용은 사용자·피용자·자영업자가 부담하는 것이 원칙이고, 국가가 관계 법령에 따라 일부를 부담할 수 있다(사회보장기본법 제28조 제2항).","c":"상","v":1},"공인노2026_35-42-2":{"f":"재정추계 세부지침에 따라 해당 연도의 10월 31일까지 실시해야 한다.","w":"중장기 사회보장 재정추계는 세부지침에 따라 해당 연도의 10월 31일까지 실시한다(사회보장기본법 시행령 제16조의3 제2항).","c":"상","v":1},"공인노2017_26-84-4":{"f":"고용보험기금의 관리ㆍ운용에 관한 세부 사항은 국가재정법의 규정에 따른다.","w":"고용보험기금의 관리·운용 세부 사항은 국고금관리법이 아니라 국가재정법을 따른다(고용보험법 제79조 제2항).","c":"상","v":1},"공인노2019_28-78-2":{"f":"1개월 미만 동안 고용된 일용근로자는 고용보험법의 적용이 제외되지 않는다.","w":"소정근로시간이 짧아 적용 제외되는 근로자라도 일용근로자는 고용보험이 적용된다(고용보험법 시행령 제3조 제2항 제2호).","c":"상","v":1},"공인노2019_28-80-3":{"f":"피보험자가 사망한 경우에는 사망한 날의 다음 날에 그 피보험자격을 상실한다.","w":"피보험자가 사망하면 사망한 날의 다음 날에 피보험자격을 잃는다(고용보험법 제14조).","c":"상","v":1},"공인노2019_28-82-3":{"f":"재심사청구인은 법정대리인 외에 자신의 형제자매를 대리인으로 선임할 수 있다.","w":"심사·재심사 청구인은 법정대리인 말고도 배우자, 직계존속·비속, 형제자매, 법인의 임직원, 변호사·공인노무사를 대리인으로 선임할 수 있다(고용보험법 제88조).","c":"상","v":1},"공인노2022_31-80-1":{"f":"고용보험 및 산업재해보상보험의 보험료징수 등에 관한 법률(이하 “고용산재보험료 징수법”이라 한다)에 따른 보험관계 성립일 전에 고용된 근로자의 경우에는 그 보험 관계가 성립한 날에 피보험자격을 취득한 것으로 본다.","w":"보험관계 성립 전에 고용된 근로자는 보험관계가 성립한 날 당일에 피보험자격을 취득한다(고용보험법 제13조).","c":"상","v":1},"공인노2022_31-84-2":{"f":"고용보험기금의 결산상 손실금이 생기는 경우 이를 적립금으로 보전(補塡)할 수 있다.","w":"결산에서 손실금이 생기면 적립금을 사용해 메울 수 있다(고용보험법 제85조).","c":"상","v":1},"공인노2022_31-85-3":{"f":"고용보험심사위원회의 재심사청구에 대한 심리는 공개함이 원칙이지만, 당사자의 양쪽 또는 어느 한 쪽이 신청한 경우에는 공개하지 아니할 수 있다.","w":"재심사청구 심리는 공개가 원칙이고, 당사자 한쪽이라도 신청하면 공개하지 않을 수 있다(고용보험법 제101조).","c":"상","v":1},"공인노2024_33-45-1":{"f":"직업안정기관 또는 근로복지공단은 심사청구서를 받은 날부터 5일 이내에 의견서를 첨부하여 심사청구서를 고용보험심사관에 보내야 한다.","w":"심사청구서를 받은 직업안정기관이나 근로복지공단은 5일 안에 의견서를 붙여 심사관에게 보내야 한다(고용보험법 제90조).","c":"상","v":1},"공인노2024_33-45-2":{"f":"고용보험심사관은 원처분등의 집행에 의하여 발생하는 중대한 위해(危害)를 피하기 위하여 긴급한 필요가 있다고 인정되면 직권으로 그 집행을 정지시킬 수 있다.","w":"심사청구만으로는 집행이 멈추지 않지만, 중대한 위해를 피할 긴급한 필요가 있으면 심사관이 직권으로 집행을 정지할 수 있다(고용보험법 제93조).","c":"상","v":1},"공인노2024_33-45-3":{"f":"육아휴직 급여와 출산전후휴가 급여등에 관한 처분에 대한 심사의 청구는 직업안정기관을 거쳐 고용보험심사관에게 하여야 한다.","w":"실업급여·육아휴직 급여·출산전후휴가 급여 등에 관한 처분의 심사청구는 직업안정기관의 장을 거친다. 근로복지공단을 거치는 것은 피보험자격 취득·상실 확인에 대한 심사청구다(고용보험법 제90조 제1항).","c":"상","v":1},"공인노2024_33-45-5":{"f":"심사청구에 대한 결정은 심사청구인 및 직업안정기관의 장 또는 근로복지공단에 결정 서의 정본을 보낸 날부터 효력이 발생한다.","w":"심사 결정은 결정서 정본을 보낸 날부터 효력이 생긴다(고용보험법 제98조).","c":"상","v":1},"공인노2024_33-47-4":{"f":"임기제 공무원이 가입한 고용보험에서 탈퇴한 이후에 가입대상 공무원으로 계속 재직하는 경우 본인의 신청에 의하여 고용보험에 다시 가입할 수 없다.","w":"고용보험에서 탈퇴한 임기제 공무원은 가입대상 공무원으로 계속 재직하는 동안 다시 가입할 수 없다(고용보험법 시행령 제3조의2 제5항).","c":"상","v":1},"공인노2024_33-53-1":{"f":"위원회의 위원장은 고용노동부차관이 되며, 위원은 고용노동부장관이 임명하거나 위촉한다.","w":"고용보험위원회 위원장은 고용노동부차관이 맞지만, 위원을 임명·위촉하는 사람은 고용노동부장관이다(고용보험법 제7조).","c":"상","v":1},"공인노2025_34-48-1":{"f":"피보험자가 이직을 한 경우에는 이직한 날의 다음 날에 그 피보험자격을 상실한다.","w":"이직하면 이직한 날의 다음 날에 피보험자격을 잃는다(고용보험법 제14조).","c":"상","v":1},"공인노2026_35-44-1":{"f":"근로자인 피보험자가 이직한 경우에는 이직한 날의 다음 날에 피보험자격을 상실한다.","w":"근로자인 피보험자는 이직한 날의 다음 날에 피보험자격을 잃는다(고용보험법 제14조).","c":"상","v":1},"공인노2026_35-44-3":{"f":"사업주는 그 사업에 고용된 근로자의 피보험자격 취득에 관한 사항을 신고하려는 경우에는 그 사유가 발생한 날이 속하는 달의 다음 달 15일까지 고용노동부장관에게 신고해야 한다.","w":"피보험자격 취득·상실 신고 기한은 사유가 생긴 달의 다음 달 15일이고, 근로자가 그보다 먼저 신고를 요구하면 지체 없이 해야 한다(고용보험법 시행령 제7조 제1항).","c":"상","v":1},"공인노2026_35-44-4":{"f":"사업주가 피보험자격에 관한 사항을 신고하지 아니하는 경우 근로자가 이를 신고할 수 있다.","w":"사업주가 신고하지 않으면 근로자가 직접 신고할 수 있다(고용보험법 제15조 제3항).","c":"상","v":1},"공인노2026_35-44-5":{"f":"근로자인 피보험자는 「고용보험 및 산업재해보상보험의 보험료징수 등에 관한 법률」제10조에 따라 보험관계가 소멸한 경우에는 그 보험관계가 소멸한 날에 피보험자격을 상실한다.","w":"보험관계가 소멸하면 그 소멸한 날 당일에 피보험자격을 잃는다. 다음 날 상실은 이직과 사망의 경우다(고용보험법 제14조 제1항).","c":"상","v":1},"공인노2026_35-45-2":{"f":"기금은 보험료의 반환의 용도로 사용할 수 있다.","w":"고용보험기금의 용도에는 보험료의 반환이 들어 있다(고용보험법 제80조 제1항 제4호).","c":"상","v":1},"공인노2026_35-45-3":{"f":"적립금에 관한 사항은 기금운용계획에 포함된다.","w":"기금운용 계획에는 기금의 수입·지출, 해당 연도 사업계획·자금계획, 전년도 이월자금 처리와 함께 적립금에 관한 사항이 들어간다(고용보험법 시행령 제109조 제4호).","c":"상","v":1},"공인노2026_35-45-4":{"f":"고용노동부장관은 대부금의 교부에 관한 업무를 「은행법」 제8조에 따른 인가를 받은 은행에 위탁할 수 있다.","w":"기금의 지원금 지급·대부금 교부·실업급여 지급 업무를 위탁받을 수 있는 곳은 은행, 농협은행, 수협은행, 상호저축은행, 새마을금고, 신용협동조합과 체신관서이고, 한국고용정보원은 들어 있지 않다(고용보험법 시행령 제108조).","c":"상","v":1},"공인노2026_35-45-5":{"f":"고용노동부장관은 「고용보험법」이 정하는 기금의 용도에 사용하기 위하여 기금을 내줄 경우 법과 영에 그 요건이 정하여져 있는 경우를 제외하고는 조건을 붙일 수 있다.","w":"법과 시행령에 요건이 정해진 경우가 아니면, 고용노동부장관은 사업 목적 달성과 기금의 효율적 운용에 필요한 범위에서 조건을 붙일 수 있다(고용보험법 시행규칙 제126조).","c":"상","v":1},"공인노2026_35-52-4":{"f":"재심사의 청구에 대한 재결은 「행정소송법」제18조(행정심판과의 관계)를 적용할 경우 행정심판에 대한 재결로 본다.","w":"고용보험심사위원회의 재심사 재결은 행정소송법 제18조를 적용할 때 행정심판 재결로 본다(고용보험법 제104조 제1항).","c":"상","v":1},"공인노2019_28-81-2":{"f":"폐업일 이전 24개월간 자영업자인 피보험자로서 갖춘 피보험 단위기간이 통산하여 1년 이상이어야 한다.","w":"자영업자의 구직급여는 폐업일 이전 24개월 동안 피보험 단위기간이 통산 1년 이상이어야 받을 수 있다(고용보험법 제69조의3). 18개월·180일은 근로자의 요건이다.","c":"상","v":1},"공인노2024_33-48-4":{"f":"실업급여로서 지급된 금품에 대하여는「국세기본법」제2조제8호의 공과금을 부과하지 아니한다.","w":"실업급여로 받은 금품에는 국세기본법상 공과금을 매기지 않는다(고용보험법 제38조의2).","c":"상","v":1},"공인노2024_33-50-1":{"f":"훈련연장급여의 지급 기간은 2년을 한도로 한다.","w":"훈련연장급여는 2년을 한도로 지급한다(고용보험법 제51조 제2항, 같은 법 시행령 제72조).","c":"상","v":1},"공인노2025_34-45-5":{"f":"훈련연장급여를 지급하는 경우에 그 일액은 해당 수급자격자의 구직급여일액의 100분의 100으로 한다.","w":"훈련연장급여 일액은 구직급여일액의 100분의 100이다. 100분의 70은 개별연장급여와 특별연장급여의 일액이다(고용보험법 제54조 제2항).","c":"상","v":1},"공인노2025_34-46-3":{"f":"수급자격자가 질병으로 직업안정기관에 출석할 수 없었던 경우로서 그 기간이 계속하여 7일 미만인 경우 그 사유를 적은 증명서를 제출하여 실업의 인정을 받을 수 있다.","w":"질병·부상으로 출석하지 못한 기간이 계속 7일 미만일 때만 증명서로 실업인정을 받을 수 있다(고용보험법 제44조 제3항 제1호). 14일이면 이 방법을 쓸 수 없다.","c":"상","v":1},"공인노2026_35-48-2":{"f":"육아휴직 시작일부터 3개월까지의 육아휴직 급여 월별 지급액은 육아휴직 시작일을 기준으로 한 월 통상임금에 해당하는 금액으로 하되, 해당 금액이 250만원을 넘는 경우에는 250만원으로 한다.","w":"육아휴직 첫 3개월은 월 통상임금 전액을 주되 상한은 250만원이고, 4~6개월째 상한이 200만원이다(고용보험법 시행령 제95조 제1항 제1호·제2호).","c":"상","v":1},"공인노2026_35-48-3":{"f":"피보험자가 육아휴직 기간 중에 그 사업에서 이직한 경우에는 그 이직하였을 때부터 육아휴직 급여를 지급하지 아니한다.","w":"육아휴직 중 그 사업에서 이직하면 이직한 때부터 육아휴직 급여가 끊긴다(고용보험법 제73조).","c":"상","v":1},"공인노2026_35-48-4":{"f":"거짓으로 육아휴직 급여를 받은 이유로 육아휴직 급여를 지급받지 못한 경우 그 급여와 관련된 육아휴직 이후에 새로 육아휴직 급여 요건을 갖추었다면 그 새로운 요건에 따른 육아휴직 급여를 지급받을 수 있다.","w":"부정수급으로 급여가 끊겨도, 그 육아휴직 뒤에 새로 요건을 갖추면 새 요건에 따른 육아휴직 급여는 받을 수 있다(고용보험법 제73조).","c":"상","v":1},"공인노2026_35-48-5":{"f":"사업주와 공모하여 거짓으로 육아휴직 급여를 받은 자는 형벌(징역 또는 벌금)의 대상이 된다.","w":"사업주와 짜고 거짓으로 육아휴직 급여를 받으면 받은 사람과 사업주 모두 5년 이하의 징역 또는 5천만원 이하의 벌금에 처한다(고용보험법 제116조). 과태료가 아니라 형벌이다.","c":"상","v":1},"공인노2017_26-91-1":{"f":"“치유”란 부상 또는 질병이 완치되거나 치료의 효과를 더 이상 기대할 수 없고 그 증상이 고정된 상태에 이르게 된 것을 말한다.","w":"증상이 고정된 상태에 이른 것은 치유의 정의다(산재보험법 제5조 제4호). 장해는 치유된 뒤에도 정신적·육체적 훼손으로 노동능력이 상실되거나 감소된 상태를 말한다.","c":"상","v":1},"공인노2017_26-91-2":{"f":"고용노동부장관은 산업재해 예방 사업에 필요한 재원을 확보하고, 보험 급여에 충당하기 위하여 산업재해보상보험및예방기금을 설치·운용한다.","w":"산업재해보상보험및예방기금을 설치하는 주체는 근로복지공단 이사장이 아니라 고용노동부장관이다(산재보험법 제95조 제1항).","c":"상","v":1},"공인노2017_26-91-4":{"f":"“업무상의 재해”란 업무상의 사유에 따른 근로자의 부상, 질병, 장해 또는 사망을 말한다.","w":"업무상 사유에 따른 부상·질병·장해·사망을 묶어 부르는 말은 업무상의 재해다(산재보험법 제5조 제1호). 업무상 사고는 업무상 재해의 한 갈래다.","c":"상","v":1},"공인노2017_26-91-5":{"f":"근로복지공단은 심사청구서를 받은 날부터 60일 이내에 산업재해보상보험심사위원회의 심의를 거쳐 심사 청구에 대한 결정을 하여야 한다.","w":"산재 심사청구 결정 기한은 심사청구서를 받은 날부터 60일이고, 부득이하면 한 차례만 20일 이내로 연장할 수 있다(산재보험법 제105조 제1항).","c":"상","v":1},"공인노2024_33-54-4":{"f":"위원회의 회의는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.","w":"산업재해보상보험및예방심의위원회는 재적위원 과반수 출석으로 개의하고 출석위원 과반수 찬성으로 의결한다(산재보험법 시행령 제7조 제3항).","c":"상","v":1},"공인노2024_33-56-2":{"f":"“평균보수”란 이를 산정하여야 할 사유가 발생한 날이 속하는 달의 전전달 말일부터 이전 3개월 동안 노무제공자가 재해가 발생한 사업에서 지급받은 보수와 같은 기간 동안 해당 사업 외의 사업에서 지급받은 보수를 모두 합산한 금액을 해당 기간의 총 일수로 나눈 금액을 말한다.","w":"노무제공자의 평균보수는 사유가 생긴 달의 전달이 아니라 전전달 말일부터 거슬러 3개월 동안 받은 보수로 계산한다(산재보험법 제91조의15 제6호).","c":"상","v":1},"공인노2024_33-59-1":{"f":"「고등교육법」제2조에 따른 학교에서 조교수 이상으로 재직하고 있는 사람은 위원이 될 수 있다.","w":"고등교육법상 학교에서 조교수 이상으로 재직하고 있거나 재직했던 사람은 업무상질병판정위원회 위원이 될 수 있다(산재보험법 시행규칙 제6조 제2항 제2호).","c":"상","v":1},"공인노2024_33-59-2":{"f":"「국가기술자격법」에 따른 산업위생관리 기사 이상의 자격을 취득하고 관련 업무에 3년 이상 종사한 치과의사는 위원이 될 수 있다.","w":"치과의사는 의사·한의사와 함께 그 자격만으로 판정위원회 위원이 될 수 있다(산재보험법 시행규칙 제6조 제2항 제3호). 자격증 경력으로 위원이 되는 길은 산업위생관리·인간공학 분야 기사 이상을 따고 관련 업무에 5년 이상 종사한 사람이다(같은 항 제5호).","c":"상","v":1},"공인노2024_33-59-4":{"f":"「국가기술자격법」에 따른 인간공학 분야 기사 이상의 자격을 취득하고 관련 업무에 3년 이상 종사한 한의사는 위원이 될 수 있다.","w":"한의사는 의사·치과의사와 함께 그 자격만으로 판정위원회 위원이 될 수 있다(산재보험법 시행규칙 제6조 제2항 제3호). 자격증 경력으로 위원이 되는 길은 산업위생관리·인간공학 분야 기사 이상을 따고 관련 업무에 5년 이상 종사한 사람이다(같은 항 제5호).","c":"상","v":1},"공인노2024_33-59-5":{"f":"위원장과 위원의 임기는 2년으로 하되, 연임할 수 있다.","w":"업무상질병판정위원회 위원장과 위원의 임기는 2년이고 연임할 수 있다(산재보험법 시행규칙 제6조 제5항).","c":"상","v":1},"공인노2024_33-60-2":{"f":"“장해”란 부상 또는 질병이 치유되었으나 정신적 또는 육체적 훼손으로 인하여 노동능력이 상실되거나 감소된 상태를 말한다.","w":"장해는 치유된 뒤에 남은 노동능력 상실·감소 상태다(산재보험법 제5조 제5호). 치유되지 않은 상태에서 노동능력이 상실·감소된 것은 중증요양상태의 정의다.","c":"상","v":1},"공인노2025_34-54-1":{"f":"공단의 상임임원과 직원은 그 직무 외에 영리를 목적으로 하는 업무에 종사하지 못한다.","w":"근로복지공단의 상임임원과 직원은 직무 외에 영리 목적 업무에 종사하지 못한다(산재보험법 제21조 제1항).","c":"상","v":1},"공인노2025_34-55-1":{"f":"국가는 회계연도마다 예산의 범위에서 보험사업에 드는 비용의 일부를 지원할 수 있다.","w":"국가는 예산 범위에서 보험사업의 사무 집행 비용을 일반회계에서 부담해야 하고, 보험사업 비용은 그 일부를 지원할 수 있다(산재보험법 제3조). 전부를 지원할 의무는 없다.","c":"상","v":1},"공인노2025_34-55-3":{"f":"“중증요양상태”란 업무상의 부상 또는 질병에 따른 정신적 또는 육체적 훼손으로 노동능력이 상실되거나 감소된 상태로서 그 부상 또는 질병이 치유되지 아니한 상태를 말한다.","w":"중증요양상태는 부상·질병이 아직 치유되지 않은 상태에서 노동능력이 상실·감소된 것이다(산재보험법 제5조 제6호). 치유된 뒤의 노동능력 상실·감소는 장해다.","c":"상","v":1},"공인노2025_34-55-4":{"f":"“치유”란 부상 또는 질병이 완치되거나 치료의 효과를 더 이상 기대할 수 없고 그 증상이 고정된 상태에 이르게 된 것을 말한다.","w":"증상이 고정된 상태에 이른 것은 치유의 정의다(산재보험법 제5조 제4호). 장해는 치유된 뒤 남은 노동능력 상실·감소 상태다.","c":"상","v":1},"공인노2025_34-55-5":{"f":"산업재해근로자의 권익 향상을 도모하기 위하여 매년 4월 28일을 산업재해근로자의 날로 하며, 산업재해근로자의 날부터 1주간을 산업재해근로자 추모 주간으로 한다.","w":"산업재해근로자의 날은 4월 28일이다(산재보험법 제9조의2 제1항).","c":"상","v":1},"공인노2026_35-59-1":{"f":"근로복지공단 소속 기관에 둔다.","w":"업무상질병판정위원회는 고용노동부가 아니라 근로복지공단 소속 기관에 둔다(산재보험법 제38조 제1항).","c":"상","v":1},"공인노2026_35-59-2":{"f":"회의는 위원장과 위원장이 회의마다 지정하는 6명의 위원으로 구성한다.","w":"판정위원회 회의는 위원장과, 회의마다 위원장이 지정하는 위원 6명으로 구성한다(산재보험법 시행규칙 제9조 제2항).","c":"상","v":1},"공인노2026_35-59-3":{"f":"위원장 1명을 포함하여 180명 이내의 위원으로 구성한다.","w":"업무상질병판정위원회는 위원장 1명을 포함한 180명 이내 위원으로 구성한다(산재보험법 시행규칙 제6조 제1항).","c":"상","v":1},"공인노2026_35-59-4":{"f":"진폐는 업무상질병판정위원회의 심의 대상에 해당하지 않는 질병이다.","w":"진폐는 업무상질병판정위원회의 심의에서 제외되는 질병이다(산재보험법 시행규칙 제7조 제1호). 진폐는 진폐심사회의를 거쳐 따로 판정한다.","c":"상","v":1},"공인노2017_26-85-5":{"f":"장의비는 유족이 아닌 자가 장제를 지낸 경우에는 평균임금의 120일분에 상당하는 금액의 범위에서 실제 드는 비용을 그 장제를 지낸 자에게 지급한다.","w":"유족이 아닌 사람이 장례를 지냈으면 평균임금 120일분을 통째로 주지 않고, 그 범위 안에서 실제 든 비용만 준다(산재보험법 제71조 제1항). 지금 법에서는 이름이 장례비로 바뀌었다.","c":"상","v":1},"공인노2017_26-86-4":{"f":"보험급여 결정등에 대하여는 행정심판법에 따른 행정심판을 제기할 수 없다.","w":"산재보험급여 결정에는 심사청구·재심사청구 절차가 따로 있으므로 행정심판법상 행정심판은 제기할 수 없다(산재보험법 제103조 제5항).","c":"상","v":1},"공인노2017_26-89-1":{"f":"보험급여는 지급 결정일부터 14일 이내에 지급하여야 한다.","w":"산재 보험급여는 지급 결정일부터 14일 안에 지급해야 한다(산재보험법 제82조 제1항).","c":"상","v":1},"공인노2017_26-89-2":{"f":"수급권자 및 보험가입자는 제3자의 행위로 재해가 발생하면 지체 없이 근로복지공단에 신고하여야 한다.","w":"제3자의 행위로 재해가 나면 수급권자와 보험가입자는 지체 없이 공단에 신고해야 한다(산재보험법 제87조 제3항). 30일이라는 기한은 없다.","c":"상","v":1},"공인노2017_26-89-3":{"f":"진폐의 진단결과에 대하여 진폐병형 및 합병증 등을 심사하기 위하여 근로복지공단에 관계 전문가 등으로 구성된 진폐심사회의를 둔다.","w":"진폐심사회의는 안전보건공단이 아니라 근로복지공단에 둔다(산재보험법 제91조의7 제1항).","c":"상","v":1},"공인노2017_26-89-4":{"f":"근로복지공단은 산재보험 의료기관이 요양급여의 산정 기준을 위반하여 부당하게 진료비를 지급받은 경우에는 그 진료비에 해당하는 금액을 징수하여야 한다.","w":"요양급여 산정 기준을 어겨 진료비를 부당하게 받은 경우는 그 진료비만큼 징수한다. 2배 징수는 거짓이나 부정한 방법으로 받은 경우다(산재보험법 제84조 제3항).","c":"상","v":1},"공인노2019_28-89-1":{"f":"부상 또는 질병이 3일 이내의 요양으로 치유될 수 있으면 요양급여를 지급하지 아니한다.","w":"요양급여를 주지 않는 기준은 3일 이내의 요양으로 치유되는 경우다(산재보험법 제40조 제3항). 이 경우는 근로기준법상 사용자가 요양보상을 한다.","c":"상","v":1},"공인노2019_28-89-3":{"f":"장해급여는 근로자가 업무상의 사유로 질병에 걸려 치유된 후 신체 등에 장해가 있는 경우에 근로복지공단에서 지급한다.","w":"장해급여를 포함한 산재 보험급여는 근로복지공단이 지급한다. 한국장애인고용공단은 산재 보험급여를 지급하지 않는다.","c":"상","v":1},"공인노2019_28-89-4":{"f":"장해보상연금의 수급권자가 재요양을 받는 경우에도 그 연금의 지급을 정지하지 아니한다.","w":"장해보상연금 수급권자가 재요양을 받아도 장해보상연금은 계속 지급한다(산재보험법 제60조).","c":"상","v":1},"공인노2019_28-89-5":{"f":"간병급여는 실제로 간병을 받는 자에게 지급한다.","w":"간병급여는 간병을 해 준 사람이 아니라 실제로 간병을 받는 사람에게 지급한다(산재보험법 제61조 제1항).","c":"상","v":1},"공인노2024_33-55-3":{"f":"근로복지공단은 근로자의 사망 당시 태아였던 자녀가 출생한 경우 유족보상연금 수급권자의 청구에 의하거나 직권으로 그 사유가 발생한 달의 다음 달분부터 유족보상연금의 금액을 조정한다.","w":"태아였던 자녀가 태어나 연금액을 조정할 때는 그 사유가 생긴 달의 다음 달분부터 조정한다(산재보험법 시행령 제63조 제1호).","c":"상","v":1},"공인노2024_33-58-1":{"f":"장례비 최고금액 및 최저금액의 적용기간은 다음 연도 1월 1일부터 12월 31일까지로 한다.","w":"장례비 최고·최저금액은 산정한 해의 다음 연도 1월 1일부터 12월 31일까지 적용한다(산재보험법 시행령 제66조 제3항). 해당 보험연도에 적용하는 것은 최고·최저 보상기준 금액이다.","c":"상","v":1},"공인노2024_33-62-2":{"f":"상병보상연금을 받는 근로자가 61세가 되면 그 이후의 상병보상연금은 고령자의 1일당 상병보상연금 지급기준에 따라 감액된 금액을 지급한다.","w":"상병보상연금 고령자 감액은 61세부터 적용된다(산재보험법 제68조).","c":"상","v":1},"공인노2024_33-62-3":{"f":"상병보상연금을 지급받는 경우 휴업급여는 지급되지 아니한다.","w":"상병보상연금은 휴업급여 대신 지급하므로 휴업급여만 끊기고 요양급여는 계속 받는다(산재보험법 제66조 제1항).","c":"상","v":1},"공인노2024_33-62-4":{"f":"재요양을 시작한 지 2년이 지난 후에 부상ㆍ질병 상태가 상병보상연금의 지급요건 모두에 해당하는 사람에게는 상병보상연금을 지급한다.","w":"재요양 중 상병보상연금은 재요양을 시작한 지 2년이 지난 뒤 지급요건을 모두 갖춰야 받을 수 있다(산재보험법 제69조 제1항).","c":"상","v":1},"공인노2024_33-62-5":{"f":"상병보상연금을 산정할 때 근로자의 평균임금이 최저임금액에 70분의 100을 곱한 금액보다 적을 때에는 최저임금액의 70분의 100에 해당하는 금액을 그 근로자의 평균임금으로 보아 산정한다.","w":"상병보상연금은 평균임금이 최저임금액의 70분의 100보다 적으면 그 금액을 평균임금으로 보고 계산한다(산재보험법 제67조 제1항).","c":"상","v":1},"공인노2025_34-57-3":{"f":"직업훈련수당의 1일당 지급액은 최저임금액에 상당하는 금액으로 한다.","w":"직업훈련수당은 1일당 최저임금액만큼 지급하고, 휴업급여나 상병보상연금을 받는 훈련대상자에게는 주지 않는다(산재보험법 제74조 제1항).","c":"상","v":1},"공인노2025_34-60-1":{"f":"보험급여는 지급 결정일부터 14일 이내에 지급하여야 한다.","w":"보험급여 지급 기한은 신청일이 아니라 지급 결정일부터 따져 14일이다(산재보험법 제82조 제1항).","c":"상","v":1},"공인노2025_34-60-2":{"f":"보험급여의 수급권자가 사망한 경우에 아직 지급되지 아니한 보험급여가 있으면 그 수급권자의 유족의 청구에 따라 그 보험급여를 지급한다.","w":"수급권자가 죽은 뒤 남은 미지급 보험급여는 유족이 청구해야 지급한다(산재보험법 제81조 제1항).","c":"상","v":1},"공인노2025_34-60-4":{"f":"근로복지공단은 보험급여를 받은 사람이 거짓이나 그 밖의 부정한 방법으로 보험급여를 받은 경우 그 급여액의 2배에 해당하는 금액을 징수하여야 한다.","w":"부정수급자에게서는 받은 급여액의 2배를 징수한다(산재보험법 제84조 제1항).","c":"상","v":1},"공인노2025_34-60-5":{"f":"근로복지공단은 거짓으로 진료비를 지급받은 산재보험 의료기관으로서 매년 직전 연도부터 과거 3년간 부정수급 횟수가 2회 이상이고 부정수급액의 합계가 1억원 이상인 자의 명단을 공개할 수 있다.","w":"명단 공개 대상은 직전 연도부터 과거 3년 동안 부정수급 2회 이상에 합계 1억원 이상인 자, 또는 1회 부정수급액이 2억원 이상인 자다(산재보험법 제84조의2 제1항).","c":"상","v":1},"공인노2025_34-62-4":{"f":"공단은 심사 청구서를 받은 날부터 60일 이내에 산업재해보상보험심사위원회의 심의를 거쳐 심사 청구에 대한 결정을 하여야 한다.","w":"산재 심사청구 결정 기한은 심사청구서를 받은 날부터 60일이고, 부득이하면 한 차례만 20일 이내로 연장할 수 있다(산재보험법 제105조 제1항).","c":"상","v":1},"공인노2026_35-56-1":{"f":"심사 청구는 보험급여 결정등이 있음을 안 날부터 90일 이내에 하여야 한다.","w":"산재 심사청구는 보험급여 결정등이 있음을 안 날부터 90일 안에 해야 한다(산재보험법 제103조 제3항).","c":"상","v":1},"공인노2026_35-56-2":{"f":"심사 청구서를 받은 근로복지공단의 소속 기관은 5일 이내에 의견서를 첨부하여 근로복지공단에 보내야 한다.","w":"공단 소속 기관은 심사청구서를 받으면 5일 안에 의견서를 붙여 근로복지공단으로 보낸다(산재보험법 제103조 제4항). 국민건강보험공단은 산재 심사와 관계가 없다.","c":"상","v":1},"공인노2026_35-56-3":{"f":"보험급여 결정등에 대하여는 「행정심판법」에 따른 행정심판을 제기할 수 없다.","w":"산재 보험급여 결정등에는 심사·재심사 청구 절차가 있으므로 행정심판법상 행정심판을 제기할 수 없다(산재보험법 제103조 제5항).","c":"상","v":1},"공인노2026_35-56-4":{"f":"「산업재해보상보험법」제84조에 따른 부당이득의 징수에 관한 결정에 대해서는 심사 청구를 할 수 있다.","w":"부당이득 징수 결정도 보험급여·진료비·약제비 결정 등과 함께 심사청구 대상이다(산재보험법 제103조 제1항 제6호).","c":"상","v":1},"공인노2017_26-93-3":{"f":"급여를 받거나 과오납금을 반환받을 수급권자 또는 가입자 등의 권리는 5년간 행사하지 아니하면 소멸시효가 완성된다.","w":"국민연금 급여와 과오납금 반환을 받을 권리는 5년, 연금보험료·환수금을 징수할 권리는 3년, 반환일시금을 받을 권리는 10년이 지나면 시효로 소멸한다(국민연금법 제115조 제1항).","c":"상","v":1},"공인노2019_28-92-1":{"f":"사실상의 혼인관계에 있는 배우자는 유족연금을 지급받을 수 있는 유족에 해당한다.","w":"국민연금법의 배우자에는 사실상 혼인관계에 있는 사람이 포함되므로 사실혼 배우자도 유족연금을 받을 수 있다(국민연금법 제3조 제2항).","c":"상","v":1},"공인노2019_28-92-2":{"f":"수급권자가 산업재해보상보험법에 의한 유족급여를 받는 경우에는 유족연금액의 2분의 1에 해당하는 금액을 지급한다.","w":"같은 사유로 산재보험 유족급여를 받으면 유족연금을 아예 끊지 않고 그 2분의 1을 지급한다(국민연금법 제113조).","c":"상","v":1},"공인노2019_28-92-3":{"f":"유족연금을 지급받을 수 있는 유족의 범위는 배우자, 자녀, 부모, 손자녀 및 조부모이다.","w":"국민연금 유족연금을 받을 수 있는 유족은 배우자·자녀·부모·손자녀·조부모이고 형제자매는 들어가지 않는다(국민연금법 제73조 제1항).","c":"상","v":1},"공인노2019_28-92-4":{"f":"유족연금 수급권자인 자녀가 사망하여도 다음 순위자인 부모에게 유족연금을 지급하지 아니한다.","w":"국민연금 유족연금은 최우선 순위자에게만 지급하고, 자녀의 수급권이 소멸했다고 부모에게 넘어가지 않는다. 다음 순위로 넘어가는 것은 배우자의 수급권이 소멸하거나 정지되어 자녀에게 지급하는 경우뿐이다(국민연금법 제73조 제2항).","c":"상","v":1},"공인노2022_31-92-1":{"f":"급여는 노령연금, 장애연금, 유족연금, 반환일시금으로 나뉜다.","w":"국민연금 급여는 노령연금·장애연금·유족연금·반환일시금 네 가지다(국민연금법 제49조).","c":"상","v":1},"공인노2022_31-92-2":{"f":"급여수급전용계좌에 입금된 급여와 이에 관한 채권은 압류할 수 없다.","w":"급여수급전용계좌에 들어온 급여와 그 채권은 압류할 수 없다(국민연금법 제58조 제3항).","c":"상","v":1},"공인노2022_31-92-3":{"f":"급여로 지급된 금액에 대하여는「조세특례제한법」이나 그 밖의 법률 또는 지방자치 단체가 조례로 정하는 바에 따라 조세, 그 밖에 국가 또는 지방자치단체의 공과금을 감면한다.","w":"국민연금 급여로 지급된 금액에는 법률이나 조례에 따라 조세와 공과금을 감면한다(국민연금법 제60조).","c":"상","v":1},"공인노2022_31-92-4":{"f":"국민연금공단은 장애연금 수급권자의 장애 정도를 심사하여 장애등급에 해당되지 아니하면 장애연금 수급권을 소멸시킨다.","w":"재심사 결과 장애등급에 해당하지 않으면 연금액을 바꾸는 것이 아니라 장애연금 수급권이 소멸한다. 연금액 변경은 장애등급이 달라진 경우다(국민연금법 제70조 제1항).","c":"상","v":1},"공인노2022_31-93-5":{"f":"임의가입자는 가입 신청이 수리된 날에 자격을 취득한다.","w":"임의가입자는 신청한 날이 아니라 가입 신청이 수리된 날에 자격을 얻는다(국민연금법 제11조 제3항).","c":"상","v":1},"공인노2024_33-64-2":{"f":"장애연금액은 장애등급 2급에 해당하는 자에 대하여는 기본연금액의 1천분의 800에 해당하는 금액에 부양가족연금액을 더한 금액으로 한다.","w":"장애연금은 1급이 기본연금액 전액, 2급이 1천분의 800, 3급이 1천분의 600에 각각 부양가족연금액을 더한 금액이다(국민연금법 제68조 제1항).","c":"상","v":1},"공인노2024_33-66-2":{"f":"국민연금심사위원회 위원의 임기는 2년으로 하며, 2차례만 연임할 수 있으며, 국민연금공단의 임직원인 위원의 임기는 그 직위의 재임기간으로 한다.","w":"국민연금심사위원회 위원은 임기 2년에 2차례까지 연임할 수 있고, 공단 임직원인 위원은 그 직위의 재임기간이 임기다(국민연금법 시행령 제91조).","c":"상","v":1},"공인노2024_33-68-5":{"f":"보건복지부장관은 국민연금기금의 운용 내용을, 재정경제부장관은 관리기금에 예탁된 국민연금기금의 사용 내용을 각각 다음 연도 6월 말까지 국민연금기금운용위원회에 제출하여야 한다.","w":"관리기금에 예탁된 기금의 사용 내용을 운용위원회에 내는 사람은 재정경제부장관(출제 당시 기획재정부장관)이다. 보건복지부장관은 기금 운용 내용만 내고, 기한은 둘 다 다음 연도 6월 말이다(국민연금법 제107조 제3항).","c":"상","v":1},"공인노2025_34-63-1":{"f":"사업장가입자는 사망한 날의 다음 날에 자격을 상실한다.","w":"사업장가입자는 사망하면 사망한 날의 다음 날에 자격을 잃는다(국민연금법 제12조 제1항 제1호).","c":"상","v":1},"공인노2025_34-63-3":{"f":"임의계속가입자는 국적을 상실한 날의 다음 날에 자격을 상실한다.","w":"임의계속가입자가 국적을 잃거나 국외로 이주하면 그날의 다음 날에 자격을 잃는다(국민연금법 제13조 제3항 제2호).","c":"상","v":1},"공인노2025_34-63-4":{"f":"임의가입자가 그 자격을 상실하게 되는 연금보험료의 체납기간은 원칙적으로 6개월이다.","w":"임의가입자와 임의계속가입자는 연금보험료를 6개월 체납하면 자격을 잃고, 천재지변 등 부득이한 사유가 있으면 예외다(국민연금법 시행령 제21조).","c":"상","v":1},"공인노2025_34-63-5":{"f":"지역가입자가 사업장가입자의 자격을 취득한 때에는 그에 해당하게 된 날에 그 자격을 상실한다.","w":"지역가입자가 사업장가입자가 되면 그날 바로 지역가입자 자격을 잃는다(국민연금법 제12조 제2항 제4호). 다음 날 상실은 사망·국적 상실 같은 경우다.","c":"상","v":1},"공인노2025_34-64-1":{"f":"연금보험료를 낸 기간이 가입대상기간의 3분의 1 이상인 가입자가 사망하면 그 유족에게 유족연금을 지급한다.","w":"연금보험료 납부기간으로 유족연금을 받으려면 낸 기간이 가입대상기간의 3분의 1 이상이어야 한다(국민연금법 제72조 제1항 제3호). 4분의 1로는 부족하다.","c":"상","v":1},"공인노2025_34-65-4":{"f":"입양으로 유족연금의 지급이 정지된 손자녀인 수급권자가 파양된 경우에는 본인의 신청에 의하여 파양된 때부터 지급 정지를 해제한다.","w":"입양으로 정지된 유족연금은 파양된 뒤 본인이 신청해야 다시 지급되고, 해제 시점도 입양된 때가 아니라 파양된 때다(국민연금법 제76조 제6항).","c":"상","v":1},"공인노2025_34-66-5":{"f":"청구인은 결정이 있기 전까지는 언제든지 심사청구를 문서로 취하할 수 있다.","w":"국민연금 심사청구는 결정 전까지 언제든 취하할 수 있지만 문서로 해야 한다(국민연금법 시행령 제98조).","c":"상","v":1},"공인노2025_34-67-2":{"f":"공단에 관하여「국민연금법」에서 정한 것 외에는「민법」중 재단법인에 관한 규정을 준용한다.","w":"국민연금공단에는 민법의 사단법인이 아니라 재단법인 규정을 준용한다(국민연금법 제48조).","c":"상","v":1},"공인노2026_35-64-1":{"f":"연금보험료를 징수하는 순위는 「국민건강보험법」에 따른 보험료와 같은 순위로 한다.","w":"연금보험료 징수 순위는 건강보험료보다 뒤가 아니라 같은 순위다(국민연금법 제98조).","c":"상","v":1},"공인노2026_35-64-3":{"f":"과오납금을 반환받을 가입자의 권리는 5년간 행사하지 아니하면 소멸시효가 완성된다.","w":"과오납금을 돌려받을 권리의 소멸시효는 5년이다(국민연금법 제115조 제1항). 3년은 연금보험료·환수금을 징수할 권리의 시효다.","c":"상","v":1},"공인노2026_35-64-4":{"f":"“평균소득월액”이란 매년 사업장가입자 및 지역가입자 전원의 기준소득월액을 평균한 금액을 말한다.","w":"평균소득월액은 사업장가입자만이 아니라 사업장가입자와 지역가입자 전원의 기준소득월액을 평균한 금액이다(국민연금법 제3조 제1항 제4호).","c":"상","v":1},"공인노2026_35-64-5":{"f":"노령연금 수급권자의 배우자로서 별도의 소득이 없는 18세 이상 60세 미만인 자는 지역가입자가 되지 아니한다.","w":"노령연금 수급권자의 배우자로서 따로 소득이 없는 사람은 지역가입자에서 제외된다(국민연금법 제9조 제1호 라목).","c":"상","v":1},"공인노2017_26-95-5":{"f":"이의신청은 처분이 있음을 안 날부터 90일 이내, 처분이 있은 날부터 180일 이내에 하여야 한다.","w":"건강보험 이의신청은 처분이 있음을 안 날부터 90일 안에 문서로 해야 하고, 처분이 있은 날부터 180일이 지나면 할 수 없다(국민건강보험법 제87조 제3항).","c":"상","v":1},"공인노2019_28-93-4":{"f":"국민건강보험공단은 지역가입자가 1개월 이상 세대단위의 보험료를 체납한 경우 그 체납한 보험료를 완납할 때까지 그 가입자 및 피부양자에 대하여 보험급여를 실시하지 아니할 수 있다.","w":"지역가입자가 세대단위 보험료를 1개월 이상 체납하면 가입자 본인과 피부양자 모두 보험급여를 받지 못하게 할 수 있다(국민건강보험법 제53조 제3항, 같은 법 시행령 제26조 제1항). 가입자를 빼고 피부양자만 제한하는 것이 아니다.","c":"상","v":1},"공인노2019_28-94-4":{"f":"직장가입자가 교직원으로서 사립학교에 근무하는 교원인 경우 보수월액보험료는 그 직장가입자가 100분의 50을, 사립학교를 설립ㆍ운영하는 자가 100분의 30을, 국가가 100분의 20을 각각 부담한다.","w":"사립학교 교원의 보수월액보험료는 본인 50%, 학교 설립·운영자 30%, 국가 20%로 나누어 낸다(국민건강보험법 제76조 제1항 단서). 50대 50으로 나누는 것은 근로자·공무원 등의 경우다.","c":"상","v":1},"공인노2022_31-94-5":{"f":"보수 관련 자료가 없거나 불명확한 경우에 해당하면 보건복지부장관이 정하여 고시하는 금액을 보수로 본다.","w":"건강보험에서 보수 자료가 없거나 불명확하면 보건복지부장관이 고시하는 금액을 보수로 본다(국민건강보험법 제70조 제3항).","c":"상","v":1},"공인노2024_33-72-4":{"f":"정당한 사유로 이의신청을 할 수 없었음을 소명한 경우가 아니면 이의신청은 처분이 있은 날부터 180일을 지나면 제기하지 못한다.","w":"이의신청은 처분이 있음을 안 날부터 90일 안에 해야 하고, 처분이 있은 날부터는 180일이 지나면 할 수 없다(국민건강보험법 제87조 제3항).","c":"상","v":1},"공인노2024_33-74-5":{"f":"휴직이나 그 밖의 사유로 보수의 전부 또는 일부가 지급되지 아니하는 가입자의 보수 월액보험료는 해당 사유가 생기기 전 달의 보수월액을 기준으로 산정한다.","w":"휴직 등으로 보수가 안 나오는 가입자의 보수월액보험료는 그 사유가 생기기 전 달의 보수월액으로 계산한다(국민건강보험법 제70조 제2항).","c":"상","v":1},"공인노2025_34-74-1":{"f":"보험료는 가입자의 자격을 취득한 날이 속하는 달의 다음 달부터 가입자의 자격을 잃은 날의 전날이 속하는 달까지 징수한다.","w":"건강보험료는 자격 취득일이 속한 달의 다음 달부터 자격을 잃은 날의 전날이 속한 달까지 걷는다(국민건강보험법 제69조 제2항).","c":"상","v":1},"공인노2025_34-74-2":{"f":"휴직이나 그 밖의 사유로 보수의 전부 또는 일부가 지급되지 아니하는 가입자의 보수 월액보험료는 해당 사유가 생기기 전 달의 보수월액을 기준으로 산정한다.","w":"휴직 등으로 보수가 안 나오는 가입자의 보수월액보험료 기준은 사유가 생기기 전 달의 보수월액이다(국민건강보험법 제70조 제2항).","c":"상","v":1},"공인노2025_34-74-3":{"f":"국외에서 업무에 종사하고 있는 직장가입자에 대한 보험료율은 정해진 보험료율의 100분의 50으로 한다.","w":"국외에서 일하는 직장가입자의 보험료율은 직장가입자 보험료율의 100분의 50이다(국민건강보험법 제73조 제2항).","c":"상","v":1},"공인노2025_34-74-5":{"f":"직장가입자가 교직원으로서 사립학교에 근무하는 교원이면 보험료액은 그 직장가입자가 100분의 50을, 사립학교를 설립ㆍ운영하는 자가 100분의 30을, 국가가 100분의 20을 각각 부담한다.","w":"사립학교 교원의 보험료는 본인 50%, 학교 설립·운영자 30%, 국가 20%다(국민건강보험법 제76조 제1항 단서).","c":"상","v":1},"공인노2026_35-70-3":{"f":"공단은 독촉을 받은 자가 그 납부기한까지 보험료등을 내지 아니하면 보건복지부장관의 승인을 받아 국세 체납처분의 예에 따라 이를 징수할 수 있다.","w":"건강보험공단이 체납처분을 하려면 국세청장이 아니라 보건복지부장관의 승인을 받는다(국민건강보험법 제81조 제3항).","c":"상","v":1},"공인노2026_35-73-1":{"f":"요양급여의 기준은 건강보험정책심의위원회의 심의ㆍ의결사항이다.","w":"요양급여의 기준은 건강보험정책심의위원회가 심의·의결한다(국민건강보험법 제4조 제1항 제2호).","c":"상","v":1},"공인노2026_35-73-2":{"f":"이송(移送)은 요양급여에 해당한다.","w":"요양급여에는 진찰·검사, 약제·치료재료, 처치·수술, 예방·재활, 입원, 간호와 함께 이송이 들어 있다(국민건강보험법 제41조 제1항).","c":"상","v":1},"공인노2026_35-73-4":{"f":"치료효과성이 불확실하여 그 검증을 위하여 추가적인 근거가 필요한 경우 선별급여를 실시할 수 있다.","w":"경제성이나 치료효과성이 불확실해 추가 근거가 필요한 경우가 바로 선별급여를 실시할 수 있는 경우다(국민건강보험법 제41조의4 제1항).","c":"하","v":1},"공인노2026_35-73-5":{"f":"요양급여를 받는 사람이 본인일부부담금을 요양기관에 납부하는 경우 요양기관은 법제41조제3항 및 제4항에 따라 보건복지부령으로 정하는 요양급여사항 또는 비급여사항 외에 입원보증금 등 다른 명목으로 비용을 청구할 수 없다.","w":"요양기관은 정해진 요양급여사항·비급여사항 말고는 입원보증금 같은 다른 명목으로 비용을 청구해서는 안 된다(국민건강보험법 시행령 제19조 제2항).","c":"상","v":1},"공인노2017_26-96-1":{"f":"보험료를 반환받을 수 있는 권리는 3년간 행사하지 아니하면 시효로 인하여 소멸한다.","w":"보험료를 징수할 권리와 반환받을 권리 모두 3년이 지나면 시효로 소멸한다(고용산재보험료징수법 제41조 제1항).","c":"상","v":1},"공인노2017_26-96-2":{"f":"월별보험료 납입을 전자문서로 고지한 경우에도 소멸시효가 중단된다.","w":"월별보험료 고지는 소멸시효 중단 사유다(고용산재보험료징수법 제42조 제1항 제1호).","c":"상","v":1},"공인노2017_26-96-3":{"f":"사업종류의 변경으로 보험료 납부방법이 변경되는 경우에는 사업종류의 변경일 전일을 변경 전 사업 폐지일로, 사업종류의 변경일을 새로운 사업성립일로 본다.","w":"사업종류가 바뀌어 납부방법이 달라지면 변경일 전날을 옛 사업 폐지일로, 변경일 당일을 새 사업 성립일로 본다(고용산재보험료징수법 제19조의2).","c":"상","v":1},"공인노2017_26-96-4":{"f":"보험료 과납액의 반환을 청구하는 경우에는 소멸시효가 중단된다.","w":"보험료 과납액 반환 청구는 소멸시효 중단 사유다(고용산재보험료징수법 제42조 제1항 제2호).","c":"상","v":1},"공인노2017_26-99-1":{"f":"고용보험료를 징수하는 경우, 근로자가 휴직기간 중에 사업주 외의 자로부터 지급받는 금품 중 고용노동부장관이 정하여 고시하는 금품은 보수로 본다.","w":"휴직 중 사업주 아닌 사람에게서 받은 금품이라도 고용노동부장관이 고시하는 금품은 보수에 들어간다(고용산재보험료징수법 제2조 제3호).","c":"상","v":1},"공인노2017_26-99-2":{"f":"“하수급인”이란 원수급인으로부터 그 사업의 전부 또는 일부를 도급받아 하는 자와 그 자로부터 그 사업의 전부 또는 일부를 도급받아 하는 자를 말한다.","w":"하수급인에는 원수급인에게서 도급받은 자뿐 아니라 그 자에게서 다시 도급받은 자도 들어간다(고용산재보험료징수법 제2조 제5호).","c":"상","v":1},"공인노2017_26-99-3":{"f":"보험에 가입한 사업주는 그 이름, 사업의 소재지 등 대통령령으로 정하는 사항이 변경된 경우에는 그 날부터 14일 이내에 그 변경사항을 근로복지공단에 신고하여야 한다.","w":"보험관계 변경 신고 기한은 변경된 날부터 14일이다(고용산재보험료징수법 제12조).","c":"상","v":1},"공인노2017_26-99-5":{"f":"보험사업에 드는 비용에 충당하기 위하여 보험가입자로부터 고용안정ㆍ직업능력개발사업 및 실업급여의 보험료, 산재보험의 보험료를 징수한다.","w":"징수하는 보험료는 고용안정·직업능력개발사업 및 실업급여의 보험료와 산재보험료 두 가지이고, 육아휴직 급여·출산전후휴가 급여의 보험료는 따로 없다(고용산재보험료징수법 제13조 제1항).","c":"상","v":1},"공인노2019_28-96-2":{"f":"원수급인으로부터 사업의 전부를 도급받아 하는 자는 하수급인에 해당한다.","w":"원수급인에게서 사업의 전부를 도급받든 일부를 도급받든 하수급인이다(고용산재보험료징수법 제2조 제5호).","c":"상","v":1},"공인노2019_28-96-3":{"f":"고용보험료를 징수하는 경우에는 근로자가 휴직기간 중에 사업주 외의 자로부터 지급 받는 금품 중 고용노동부장관이 정하여 고시하는 금품은 보수로 본다.","w":"휴직 중 사업주 외의 자에게서 받은 금품 가운데 고용노동부장관이 고시하는 금품은 보수에 포함된다(고용산재보험료징수법 제2조 제3호).","c":"상","v":1},"공인노2019_28-96-4":{"f":"보험에 가입한 사업주는 사업의 명칭 및 소재지, 사업의 종류 등이 변경된 경우에는 그 변경된 날부터 14일 이내에 그 변경사항을 근로복지공단에 신고하여야 한다.","w":"변경 신고 기한은 다음 보험연도 첫날이 아니라 변경된 날부터 14일이다(고용산재보험료징수법 제12조).","c":"상","v":1},"공인노2019_28-96-5":{"f":"산업재해보상보험법을 적용하지 아니하는 사업의 사업주는 근로복지공단의 승인을 받아 산업재해보상보험에 가입할 수 있다.","w":"산재보험법이 적용되는 사업의 사업주는 당연히 가입자가 된다. 공단 승인을 받아 가입하는 것은 산재보험법이 적용되지 않는 사업의 사업주다(고용산재보험료징수법 제5조 제3항·제4항).","c":"상","v":1},"공인노2019_28-98-3":{"f":"국민건강보험공단은 소멸시효가 완성된 경우에는 고용노동부장관의 승인을 받아 보험료와 이 법에 따른 그 밖의 징수금을 결손처분할 수 있다.","w":"보험료 결손처분은 근로복지공단이 아니라 징수를 맡은 국민건강보험공단이 고용노동부장관의 승인을 받아 한다(고용산재보험료징수법 제29조 제1항).","c":"상","v":1},"공인노2019_28-100-2":{"f":"보험료율이 인상된 경우 근로복지공단은 개산보험료를 증액 조정한다.","w":"보험료율이 바뀌면 월별보험료와 개산보험료를 조정하는 곳은 근로복지공단이다. 증액된 월별보험료는 국민건강보험공단이, 증액된 개산보험료는 근로복지공단이 징수한다(고용산재보험료징수법 제18조 제1항).","c":"상","v":1},"공인노2022_31-97-2":{"f":"일괄적용사업의 사업주는 사업의 개시일부터 14일 이내에 끝나는 사업의 경우에는 그 끝나는 날의 전날까지 개시 및 종료 사실을 근로복지공단에 신고하여야 한다.","w":"일괄적용사업 가운데 개시일부터 14일 안에 끝나는 사업은 끝나는 날의 전날까지 개시와 종료를 신고해야 한다(고용산재보험료징수법 제11조 제3항 단서).","c":"상","v":1},"공인노2022_31-99-1":{"f":"근로시간에 따라 보수를 지급받는 근로자가 주당 소정근로시간을 확정할 수 없는 경우에는 월단위 기준보수를 적용한다.","w":"시간급 근로자에게는 원래 시간단위 기준보수를 적용하지만, 주당 소정근로시간을 확정할 수 없으면 월단위 기준보수를 적용한다(고용산재보험료징수법 시행령 제3조 제4항 제2호 단서).","c":"상","v":1},"공인노2024_33-75-1":{"f":"자영업자에 대한 고용보험료 산정의 기초가 되는 보수액은 자영업자의 소득, 보수수준 등을 고려하여 고용노동부장관이 정하여 고시한다.","w":"자영업자 고용보험료의 기준 보수액은 기획재정부장관이 아니라 고용노동부장관이 고시한다(고용산재보험료징수법 제49조의2 제3항).","c":"상","v":1},"공인노2024_33-75-2":{"f":"고용보험에 가입한 자영업자는 매월 부과된 보험료를 다음 달 10일까지 납부하여야 한다.","w":"고용보험에 가입한 자영업자는 매월 부과된 보험료를 다음 달 10일까지 낸다(고용산재보험료징수법 제49조의2 제9항).","c":"상","v":1},"공인노2024_33-75-3":{"f":"자영업자의 고용보험료는 근로복지공단이 매월 부과하고 국민건강보험공단이 징수한다.","w":"자영업자 고용보험료는 근로복지공단이 매월 부과하고 국민건강보험공단이 징수한다(고용산재보험료징수법 제49조의2 제8항).","c":"상","v":1},"공인노2024_33-75-4":{"f":"고용보험에 가입한 자영업자가 자신에게 부과된 월(月)의 고용보험료를 계속하여 6개월간 납부하지 아니한 경우에는 마지막으로 납부한 고용보험료에 해당되는 피보험기간의 다음날에 보험관계가 소멸된다.","w":"자영업자의 보험관계는 고용보험료를 계속 6개월 동안 내지 않았을 때 소멸한다(고용산재보험료징수법 제49조의2 제10항). 3개월 체납만으로는 소멸하지 않는다.","c":"상","v":1},"공인노2024_33-78-4":{"f":"근로복지공단은 사업주가 보험연도 중에 사업의 규모를 축소하여 실제의 개산보험료 총액이 이미 신고한 개산보험료 총액보다 100분의 30 이상으로 감소하게 된 경우에는 사업주의 신청을 받아 그 초과액을 감액할 수 있다.","w":"개산보험료 감액은 실제 총액이 신고액보다 100분의 30 이상 줄었을 때 사업주가 신청하면 공단이 할 수 있다(고용산재보험료징수법 제18조 제2항, 같은 법 시행령 제25조). 100분의 20 기준도, 감액 의무도 없다.","c":"상","v":1},"공인노2025_34-76-1":{"f":"보험관계는 사업이 폐업되거나 끝난 날의 다음 날 소멸한다.","w":"사업이 폐업하거나 끝나면 그날의 다음 날에 보험관계가 소멸한다(고용산재보험료징수법 제10조 제1호).","c":"상","v":1},"공인노2025_34-76-2":{"f":"일괄적용을 받는 사업의 경우에는 처음 하는 사업이 시작된 날에 보험관계가 성립한다.","w":"일괄적용 사업의 보험관계는 처음 하는 사업이 시작된 날 당일에 성립한다(고용산재보험료징수법 제7조 제4호).","c":"상","v":1},"공인노2025_34-76-3":{"f":"근로복지공단의 승인을 얻어 가입한 보험계약을 해지하는 경우에는 그 해지에 관하여 근로복지공단의 승인을 받은 날의 다음 날에 보험관계가 소멸한다.","w":"임의가입한 보험계약을 해지하면 공단 승인을 받은 날의 다음 날에 보험관계가 소멸한다(고용산재보험료징수법 제10조 제2호).","c":"상","v":1},"공인노2025_34-76-4":{"f":"보험에 가입한 하수급인의 경우에는 그 하도급공사의 착공일에 보험관계가 성립한다.","w":"보험에 가입한 하수급인의 보험관계는 하도급공사 착공일 당일에 성립한다(고용산재보험료징수법 제7조 제5호).","c":"상","v":1},"공인노2025_34-77-3":{"f":"상시근로자 수가 3명인 농업 법인의 사업주는 당연히 산업재해보상보험의 보험가입자가 된다.","w":"산재보험법 적용 제외는 농업·임업·어업·수렵업 가운데 법인이 아닌 자의 사업으로서 상시근로자 5명 미만인 경우다(산재보험법 시행령 제2조 제1항 제6호). 법인이면 근로자 수와 관계없이 당연가입자가 된다(고용산재보험료징수법 제5조 제3항).","c":"상","v":1},"공인노2025_34-78-1":{"f":"보험료, 이 법에 따른 그 밖의 징수금을 징수할 수 있는 권리는 3년간 행사하지 아니하면 시효로 인하여 소멸하며, 소멸시효에 관하여는 이 법에 규정된 것을 제외하고는 「민법」에 따른다.","w":"징수권의 시효는 3년이고, 소멸시효는 징수법에 규정된 것을 빼고 민법에 따른다(고용산재보험료징수법 제41조). 민법이 우선 적용되는 것이 아니다.","c":"상","v":1},"공인노2025_34-78-2":{"f":"이 법에 따른 징수금의 독촉에 따라 중단된 소멸시효는 독촉에 의한 납부기한이 지난 때부터 새로 진행한다.","w":"독촉으로 중단된 시효는 독촉한 날이 아니라 독촉에 따른 납부기한이 지난 때부터 다시 진행한다(고용산재보험료징수법 제42조 제2항 제2호).","c":"상","v":1},"공인노2025_34-78-4":{"f":"이 법에 따른 체납처분 절차에 따라 하는 교부청구로 중단된 소멸시효는 교부청구 중의 기간이 지난 때부터 새로 진행한다.","w":"교부청구로 중단된 시효는 교부청구 중의 기간이 지난 때부터 다시 진행한다(고용산재보험료징수법 제42조 제2항 제4호).","c":"상","v":1},"공인노2025_34-78-5":{"f":"월별보험료의 고지로 중단된 소멸시효는 고지한 월별보험료의 납부기한이 지난 때부터 새로 진행한다.","w":"고지로 중단된 시효는 고지한 날이 아니라 고지한 월별보험료의 납부기한이 지난 때부터 다시 진행한다(고용산재보험료징수법 제42조 제2항 제1호).","c":"상","v":1},"공인노2025_34-79-1":{"f":"고용보험료율은 보험수지와 경제상황 등을 고려하여 1000분의 30의 범위에서 고용안정ㆍ직업능력개발사업의 보험료율 및 실업급여의 보험료율로 구분하여 정한다.","w":"고용보험료율의 상한은 1000분의 30이다(고용산재보험료징수법 제14조 제1항).","c":"상","v":1},"공인노2025_34-79-3":{"f":"산업재해보상보험의 보험관계가 성립한 후 3년이 지나지 아니한 사업에 대한 산재보험료율은 사업의 종류별로 따로 정한다.","w":"보험관계 성립 후 3년이 지나지 않은 사업의 산재보험료율은 산업재해보상보험및예방심의위원회 심의를 거쳐 고용노동부장관이 사업의 종류별로 따로 정한다(고용산재보험료징수법 제14조 제4항). 4년도 아니고 모두 같은 요율로 정하지도 않는다.","c":"상","v":1},"공인노2025_34-79-4":{"f":"산재보험료율을 정하는 경우에는 특정 사업 종류의 산재보험료율이 전체 사업의 평균 산재보험료율의 20배를 초과하지 아니하도록 하여야 한다.","w":"특정 업종의 산재보험료율은 전체 사업 평균 산재보험료율의 20배를 넘을 수 없다(고용산재보험료징수법 제14조 제5항).","c":"상","v":1},"공인노2025_34-79-5":{"f":"고용노동부장관은 관련 규정에 따라 정한 특정 사업 종류의 산재보험료율이 인상되거나 인하되는 경우에는 직전 보험연도 산재보험료율의 100분의 30의 범위에서 조정하여야한다.","w":"업종별 산재보험료율을 올리거나 내릴 때 조정 폭은 직전 보험연도 요율의 100분의 30 이내다(고용산재보험료징수법 제14조 제6항).","c":"상","v":1},"공인노2025_34-80-1":{"f":"사업종류의 변경으로 보험료 납부방법이 변경되는 경우에는 사업종류의 변경일 전일을 변경 전 사업 폐지일로, 사업종류의 변경일을 새로운 사업성립일로 본다.","w":"사업종류가 바뀌어 납부방법이 달라지면 변경일 전날을 옛 사업 폐지일로, 변경일 당일을 새 사업 성립일로 본다(고용산재보험료징수법 제19조의2).","c":"상","v":1},"공인노2025_34-80-2":{"f":"사업주는 그 달의 월별보험료를 다음 달 10일까지 납부하여야 하며, 보험료의 정산에 따라 산정된 보험료는 국민건강보험공단이 정하여 고지한 기한까지 납부하여야 한다.","w":"월별보험료 납부기한은 그 달 말일이 아니라 다음 달 10일이다. 정산에 따라 산정된 보험료의 납부기한을 정해 고지하는 곳도 근로복지공단이 아니라 국민건강보험공단이다(고용산재보험료징수법 제16조의7).","c":"상","v":1},"공인노2025_34-80-3":{"f":"국민건강보험공단은 사업주에게 징수하고자 하는 보험료 등의 종류, 납부할 금액 등을 적은 문서로써 납부기한 10일 전까지 월별보험료의 납입을 고지하여야 한다.","w":"월별보험료 납입 고지는 징수를 맡은 국민건강보험공단이 납부기한 10일 전까지 문서로 한다(고용산재보험료징수법 제16조의8 제1항).","c":"상","v":1},"공인노2025_34-80-4":{"f":"근로복지공단은 보험료율이 인상 또는 인하된 때에는 개산보험료를 증액 또는 감액 조정하고, 이를 징수한다.","w":"개산보험료의 조정과 증액분 징수는 근로복지공단이 한다(고용산재보험료징수법 제18조 제1항). 국민건강보험공단은 증액된 월별보험료를 징수한다.","c":"상","v":1},"공인노2026_35-75-1":{"f":"「고용보험법」을 적용하지 아니하는 사업의 사업주로서 고용보험에 가입한 사업주가 고용보험계약을 해지할 때에는 근로자 과반수의 동의를 받아야 한다.","w":"임의가입한 고용보험계약을 해지할 때 필요한 동의는 근로자 과반수다(고용산재보험료징수법 제5조 제6항).","c":"상","v":1},"공인노2026_35-75-3":{"f":"사업의 일괄적용을 받고 있는 사업주가 일괄적용관계의 해지 승인을 받으려는 경우에는 다음 보험연도가 시작되기 7일 전까지 이를 신청하여야 한다.","w":"일괄적용관계 해지 승인 신청은 다음 보험연도 개시 7일 전까지 해야 한다(고용산재보험료징수법 시행령 제6조 제3항).","c":"상","v":1},"공인노2026_35-75-4":{"f":"근로복지공단은 사업 실체가 없는 등의 사유로 계속하여 보험관계를 유지할 수 없다고 인정하는 경우에는 그 보험관계를 소멸시킬 수 있다.","w":"보험관계를 직권으로 소멸시키는 곳은 근로복지공단이고, 소멸 여부는 재량이다(고용산재보험료징수법 제5조 제7항).","c":"상","v":1},"공인노2026_35-75-5":{"f":"일괄적용을 받고 있는 사업이 사업의 폐업으로 일괄적용관계가 소멸한 경우에는 사업주는 소멸한 날부터 14일 이내에 일괄적용관계의 소멸 신고를 하여야 한다.","w":"일괄적용관계가 소멸하면 사업주는 소멸한 날부터 14일 안에 공단에 소멸 신고를 한다(고용산재보험료징수법 제11조 제2항).","c":"상","v":1},"공인노2026_35-76-1":{"f":"법인이 보험사무를 대행하려는 경우에는 대통령령으로 정하는 바에 따라 근로복지공단의 인가를 받아야 한다.","w":"보험사무대행기관 인가는 국민건강보험공단이 아니라 근로복지공단이 한다(고용산재보험료징수법 제33조 제2항).","c":"상","v":1},"공인노2026_35-77-1":{"f":"체납된 보험료등의 분할 납부를 승인받으려는 사업주는 납부 독촉에 따라 고지된 납부기한 만료일까지 체납 보험료등의 분할 납부 승인신청서를 국민건강보험공단에 제출해야 한다.","w":"분할 납부 승인신청서는 독촉에 따라 고지된 납부기한 만료일까지 국민건강보험공단에 낸다(고용산재보험료징수법 시행규칙 제32조의3 제1항). 만료일 3일 전이 기한은 아니다.","c":"상","v":1},"공인노2026_35-77-2":{"f":"납부기한이 지난 보험료의 분할 납부의 총 기간은 분할 납부의 승인을 받은 날의 다음 날부터 2년 이내로 한다.","w":"분할 납부 총기간은 승인을 받은 날의 다음 날부터 2년 이내다(고용산재보험료징수법 시행규칙 제32조의3 제2항).","c":"상","v":1},"공인노2026_35-77-4":{"f":"천재지변으로 납부기한이 연장되었으나 연장된 납부기한이 지나 5회 체납한 경우에도 분할 납부의 승인을 신청할 수 있다.","w":"천재지변 등으로 연장된 납부기한이 지나 3회 이상 체납한 사업주는 분할 납부를 신청할 수 있으므로 5회 체납했어도 신청할 수 있다(고용산재보험료징수법 제27조의3 제1항 제2호).","c":"상","v":1},"공인노2026_35-77-5":{"f":"분할 납부 승인을 취소하는 경우에는 분할 납부의 대상이 되는 보험료와 이 법에 따른 그 밖의 징수금을 한꺼번에 징수할 수 있다.","w":"분할 납부 승인을 취소하면 분할 납부 대상 보험료와 그 밖의 징수금을 한꺼번에 징수할 수 있다(고용산재보험료징수법 제27조의3 제4항).","c":"상","v":1},"공인노2017_26-78":{"w":"사회보장기본법 제16조 제1항: 사회보장 기본계획은 5년마다 수립한다.\n제5조 제4항: 중장기 사회보장 재정추계는 격년으로 실시하고 공표한다.","c":"상"},"공인노2022_31-78":{"w":"사회보장기본법 시행령: 보건복지부장관은 평가지침을 매년 1월 31일까지 관계 중앙행정기관의 장에게 통보하고, 관계 중앙행정기관의 장은 전년도 추진실적 평가 결과를 매년 3월 31일까지 보건복지부장관에게 제출한다.","c":"중"},"공인노2024_33-41":{"w":"사회보장기본법 시행령의 위탁 대상은 정부출연연구기관, 고등교육법상 학교, 특정연구기관, 국공립 연구기관 등이다. 네 곳 모두 재정추계·사회보장통계 관련 자료 수집·조사·분석 업무를 위탁받을 수 있다.","c":"중"},"공인노2026_35-43":{"w":"사회보장제도 평가 지원 업무의 위탁 대상은 국공립 연구기관, 고등교육법상 학교, 특정연구기관, 공공기관운영법상 공공기관, 정부출연연구기관 등 공적 연구·전문기관이다.\n민법 제32조에 따라 설립된 법인은 위탁 대상으로 정해져 있지 않다.","c":"중"},"공인노2017_26-79":{"w":"출제 당시(2017) 시행령은 육아기 근로시간 단축 급여를 월 통상임금의 100분의 60에 단축 비율을 곱해 계산했다.\n200만원 × 60/100 × (40 − 30)/40 = 30만원\n지금 시행령은 매주 최초 10시간 단축분에 월 통상임금의 100%(상한 있음)를 적용한다. 같은 조건이면 200만원 × 10/40 = 50만원이 되어 정답이 ④로 바뀐다.","c":"의심","old":1,"ow":"출제 당시 정답 ②(30만원, 통상임금의 60% 기준). 지금은 매주 최초 10시간 단축분까지 통상임금의 100%를 주므로 200만원×10/40=50만원이 되어 정답이 ④로 바뀐다(고용보험법 시행령 제104조의2)."},"공인노2017_26-80":{"w":"고용보험법 시행령 제17조의 고용창출 지원은 교대근로 개편 등으로 실업자를 고용해 근로자 수가 늘어난 경우, 시간제직무 개발로 기간의 정함이 없는 시간제 근로자를 새로 고용한 경우, 고용환경 개선 시설을 설치·운영하고 실업자를 고용한 경우, 인력수급 불일치 업종 기업이 실업자를 고용한 경우, 고용보험위원회가 정한 업종의 '우선지원 대상기업'이 전문 자격을 갖춘 사람을 고용한 경우다.\n⑤처럼 대규모기업이 전문인력을 고용한 경우는 지원 대상이 아니다.","c":"상"},"공인노2017_26-82":{"w":"출제 당시(2017) 별표 1 기준으로는 ⑤가 맞았다(피보험기간 10년 이상, 30세 이상 50세 미만: 210일). 같은 표로 ①은 120일, ②는 150일, ③은 150일, ④는 210일이다.\n2019년 10월 1일부터 소정급여일수가 50세 미만/50세 이상·장애인 두 구간으로 바뀌고 30일씩 늘었다. 현행 별표로는 ① 180일, ② 180일, ③ 180일, ④ 240일, ⑤ 240일이어서 맞는 선지가 없다.","c":"의심","old":1,"ow":"출제 당시 정답 ⑤. 2019.10.1 시행 개정으로 소정급여일수가 늘어 지금은 ① 180일 ② 180일 ③ 180일 ④ 240일 ⑤ 240일이므로 맞는 선지가 없다(고용보험법 제50조 별표 1)."},"공인노2019_28-84":{"w":"고용보험법 제38조 제2항과 시행령 제58조의3: 실업급여수급계좌의 예금 중 그 계좌에 입금된 금액 전액 이하의 금액에 관한 채권은 압류할 수 없다.","c":"상"},"공인노2022_31-82":{"w":"고용보험법 별표 2(자영업자 소정급여일수): 피보험기간 1년 이상 3년 미만 120일, 3년 이상 5년 미만 150일, 5년 이상 10년 미만 180일, 10년 이상 210일.\n① 6개월은 1년 미만이어서 수급 요건(피보험 단위기간 1년)에 못 미친다. ②는 120일, ③은 150일, ⑤는 210일이어야 한다.","c":"상"},"공인노2024_33-44":{"w":"별표 1에서 장애인은 50세 이상과 같은 구간을 쓴다. 피보험기간 1년 이상 3년 미만이면 180일이다.","c":"상"},"공인노2024_33-46":{"w":"출제 당시 고용보험법 시행령의 부모 공동 육아휴직 특례: 7개월째부터 종료일까지는 월 통상임금의 100분의 80, 상한 150만원, 하한 70만원.\n2025년부터 육아휴직 급여 체계가 다시 바뀌었으므로 현행 금액은 별도로 본다.","c":"중","old":1,"ow":"출제 당시 정답 ④(100분의 80, 150만원). 2025년 육아휴직 급여 인상으로 7개월째부터는 통상임금의 80%에 상한 월 160만원이므로 ㄴ이 160이 되어 맞는 선지가 없다(고용보험법 시행령 제95조)."},"공인노2024_33-49":{"w":"제77조의3 제1항 단서에 따라 최종 이직 당시 단기예술인에게만 붙는 요건은 두 가지다.\nㄱ O 신청일 이전 1개월 노무제공일수 10일 미만 또는 14일간 연속 노무제공 내역 없음\nㄹ O 수급자격 제한 사유로 이직한 사실이 있으면 그 기간 중 90일 이상 단기예술인으로 종사\nㄴ·ㄷ·ㅁ은 모든 예술인에게 공통인 요건이다.","c":"상"},"공인노2024_33-51":{"w":"고용보험법 제54조 제2항: 훈련연장급여 일액은 구직급여일액의 100분의 100, 개별연장급여·특별연장급여 일액은 구직급여일액의 100분의 70이다.","c":"상"},"공인노2024_33-52":{"w":"고용보험법 시행령: 둘 이상의 고용유지조치를 동시에 실시한 날은 1일로 보고, 실시 일수 합계가 그 보험연도에 180일에 이를 때까지만 고용유지지원금을 지급한다.","c":"상"},"공인노2025_34-47":{"w":"시행령 별표 1의 우선지원 대상기업 기준: 제조업 500명 이하, 광업·건설업·운수창고업·정보통신업·사업지원서비스업·전문과학기술서비스업·보건업 및 사회복지 서비스업 300명 이하, 도소매업·숙박음식점업·금융보험업·예술스포츠여가업 200명 이하, 그 밖의 업종 100명 이하.\n산업용 기계 및 장비 수리업은 제조업에서 빼서 그 밖의 업종으로 보므로 100명 이하다.\n② 건설업 300명, ③ 금융보험업 200명, ④ 보건업 300명, ⑤ 숙박음식점업 200명이 맞는 기준이다.","c":"상"},"공인노2025_34-49":{"w":"고용보험법 제37조: 실업급여는 구직급여와 취업촉진 수당(조기재취업 수당, 직업능력개발 수당, 광역 구직활동비, 이주비)이다.\n장해급여는 산업재해보상보험법의 보험급여다.","c":"상"},"공인노2025_34-50":{"w":"별표 1에서 장애인은 50세 이상 구간을 쓴다. 피보험기간 3년 이상 5년 미만이면 210일이다.","c":"상"},"공인노2025_34-51":{"w":"시행규칙 별표 2의 정당한 이직 사유로 판단한다.\nㄱ X 임금체불은 이직일 전 1년 이내에 2개월 이상 발생한 경우 등이어야 한다. 1개월로는 안 된다.\nㄴ O, ㄷ O 정년 도래나 계약기간 만료로 계속 근무할 수 없게 된 경우\nㄹ O 성별·종교·정치적 견해·장애 등을 이유로 불합리한 차별을 받은 경우\nㅁ O 동거 친족의 질병 등으로 30일 이상 간호가 필요한데 휴가가 허용되지 않아 이직한 경우","c":"상"},"공인노2025_34-52":{"w":"시행령의 육아휴직 급여 신청기간 연장 사유는 천재지변, 본인이나 배우자의 질병·부상, 본인이나 배우자의 직계존속·직계비속의 질병·부상, 병역법에 따른 의무복무, 범죄혐의로 인한 구속이나 형 집행이다.\nㄹ 형제자매의 부상은 사유가 아니다.","c":"상"},"공인노2025_34-53":{"w":"시행규칙의 이주비 지급 요건에 세 개 모두 들어 있다.\nㄱ 직업안정기관의 장이 주거 변경이 필요하다고 인정\nㄴ 사업주가 이전 비용을 주지 않거나 이주비보다 적게 지급\nㄷ 취업을 위한 이주이면 1년 이상의 근로계약기간","c":"상"},"공인노2026_35-46":{"w":"고용보험법 제37조 제2항: 취업촉진 수당은 조기재취업 수당, 직업능력개발 수당, 광역 구직활동비, 이주비다.\nㄱ 구직급여는 실업급여이지만 취업촉진 수당이 아니다.","c":"상"},"공인노2026_35-47":{"w":"제77조의3 제1항: 이직일 이전 24개월 동안 피보험 단위기간이 통산 9개월 이상이고, 그 24개월 중 3개월 이상을 예술인인 피보험자로 자격을 유지했어야 한다.","c":"상"},"공인노2026_35-50":{"w":"시행규칙 별표 2에서 임금체불로 인한 정당한 이직은 이직일 전 1년 이내에 2개월 이상 체불이 발생한 경우 등이다. 1개월로는 정당한 이직 사유가 되지 않는다.\n② 성희롱, ③ 노조활동 이유 차별, ④ 도산·폐업 확실 또는 대량 감원 예정, ⑤ 정년·계약 만료는 모두 별표 2에 있다.","c":"상"},"공인노2017_26-81":{"w":"ㄱ O 제2조 제3호\nㄴ X 제2조 제6호: 일용근로자는 1개월 미만 동안 고용되는 사람이다.\nㄷ X 제2조 제2호: 이직은 피보험자와 사업주 사이의 고용관계가 끝나게 되는 것이다. 새 사업주와 계약하는 것까지 요구하지 않는다.","c":"상"},"공인노2017_26-83":{"w":"ㄱ 징역·벌금 거짓이나 부정한 방법으로 실업급여·육아휴직 급여 등을 받은 자는 제116조에 따라 징역 또는 벌금에 처한다.\nㄴ 과태료 피보험자격 취득·상실 신고 의무 위반\nㄷ 과태료 이직확인서 거짓 작성·제출","c":"상"},"공인노2019_28-83":{"w":"고용보험법 제80조의 기금 용도: 고용안정·직업능력개발 사업 경비, 실업급여 지급, 국민연금 보험료 지원(제55조의2), 육아휴직 급여·출산전후휴가 급여 등, 보험료 반환, 일시 차입금 상환, 징수법 업무 대행·위탁 출연금 등.\nㅁ 국민건강보험료 지원은 용도에 없다.","c":"상"},"공인노2022_31-81":{"w":"ㄱ O, ㄴ O 고용보험법 제10조: 공무원연금·군인연금·사학연금·별정우체국법 적용자는 적용 제외다.\nㄷ O 시행령 제2조: 농업·임업·어업·수렵업 중 법인이 아닌 자가 상시 4명 이하 근로자를 사용하는 사업은 적용 제외다.","c":"상"},"공인노2022_31-83":{"w":"시행령의 노무제공자 직종에 방문판매원이 들어 있지만, 방문판매는 하지 않고 자가 소비만 하는 후원방문판매원은 빠진다.\n①·②·③·⑤는 노무제공자 직종이다.","c":"상"},"공인노2025_34-44":{"w":"고용보험법 제80조의 기금 용도에 다섯 개 모두 있다. 일시 차입금 상환금과 이자, 국민연금 보험료 지원, 실업급여 지급에 딸린 경비, 육아휴직·출산전후휴가 급여, 징수법 업무 대행·위탁자 출연금.","c":"상"},"공인노2026_35-49":{"w":"시행령의 노무제공자 직종 중 신용카드회원 모집인은 전업으로 하는 사람만 해당한다. 부업으로 하는 사람까지 포함한 ④는 노무제공자 범위를 넘는다.\n①·②·③·⑤는 노무제공자 직종이다.","c":"중"},"공인노2026_35-51":{"w":"ㄱ X 고용보험법 시행령 제1조의7 제1항: 위원회에 두는 전문위원회는 고용보험운영전문위원회와 고용보험평가전문위원회다.\nㄴ X 고용보험법 제7조 제3항·제4항: 위원장 1명을 포함한 20명 이내로 구성하고, 위원은 근로자·사용자·공익·정부를 대표하는 사람을 같은 수로 고용노동부장관이 임명·위촉한다. 상임위원 규정은 없다.\nㄷ O 제7조 제2항 제2호: 고용산재보험료징수법에 따른 보험료율 결정은 심의 사항이다.\nㄹ O 시행령 제1조의8 제1항: 위원회에 5명 이내의 조사·연구위원을 둘 수 있다.","c":"상","v":1},"공인노2026_35-53":{"w":"고용보험법 제93조: 심사관은 원처분등의 집행으로 생길 중대한 위해를 피하기 위해 긴급한 필요가 있으면 직권으로 집행을 정지할 수 있고, 그 사실을 이유를 적은 문서로 직업안정기관의 장 또는 근로복지공단에 알린다.","c":"상"},"공인노2017_26-87":{"w":"산재보험법 제54조 제1항: 1일당 휴업급여가 최저 보상기준 금액의 100분의 80보다 적거나 같으면 평균임금의 100분의 90을 휴업급여로 한다.","c":"상"},"공인노2019_28-85":{"w":"산재보험법 제112조: 장해급여, 유족급여, 장례비(장의비), 진폐보상연금, 진폐유족연금을 받을 권리는 5년, 나머지 보험급여 권리는 3년이다.\n요양급여·간병급여·상병보상연금·직업재활급여는 3년이고 장의비만 5년이다.","c":"상"},"공인노2019_28-86":{"w":"산재보험법 제58조의 장해보상연금 수급권 소멸 사유에 네 개 모두 있다. 수급권자 사망, 국민이었던 수급권자의 국적 상실 후 외국 거주, 외국인 수급권자의 외국 거주 목적 출국, 장해등급 변경으로 연금 지급 대상에서 빠진 경우.","c":"상"},"공인노2019_28-88":{"w":"산재보험법 제103조의 심사청구 대상은 보험급여 결정, 진료비 결정, 약제비 결정, 진료계획 변경 조치, 보험급여 일시지급 결정, 합병증 예방관리 조치, 부당이득 징수 결정, 수급권 대위 결정 등이다.\n보험료 부과는 징수법에 따른 처분이어서 산재보험법상 심사청구 대상이 아니다.","c":"상"},"공인노2022_31-89":{"w":"산재보험법 제66조 제1항: 요양급여를 받는 근로자가 요양 시작 후 2년이 지난 날 이후에 부상·질병이 치유되지 않았고, 중증요양상태등급 기준에 해당하며, 요양으로 취업하지 못했으면 상병보상연금을 지급한다. 세 요건 모두 필요하다.","c":"상"},"공인노2022_31-91":{"w":"산재보험법 제54조 제1항: 최저 보상기준 금액의 100분의 80 이하이면 평균임금의 100분의 90을 지급하되, 그 금액이 최저 보상기준 금액의 100분의 80보다 많으면 최저 보상기준 금액의 100분의 80을 지급한다.","c":"상"},"공인노2024_33-57":{"w":"산재보험법 제40조 제4항의 요양급여 범위는 진찰·검사, 약제·진료재료·의지 등 보조기 지급, 처치·수술 등 치료, 재활치료, 입원, 간호 및 간병, 이송 등이다. 다섯 개 모두 해당한다.","c":"상"},"공인노2024_33-61":{"w":"산재보험법 제57조 제4항: 최초 1년분 또는 2년분(노동력 완전 상실 등급은 1년분부터 4년분까지)의 2분의 1에 해당하는 금액을 미리 지급할 수 있고, 이자는 100분의 5 범위에서 공제한다.\n2 + 4 + 2 + 5 = 13","c":"상"},"공인노2024_33-63":{"w":"산재보험법 제75조: 직장복귀지원금 지급기간은 12개월 이내, 직장적응훈련비와 재활운동비 지급기간은 3개월 이내다.","c":"상"},"공인노2025_34-56":{"w":"ㄱ O 제36조 제1항 단서: 진폐 보험급여는 요양급여, 간병급여, 장례비, 직업재활급여, 진폐보상연금, 진폐유족연금이다.\nㄴ O 제91조의12: 임신 중 업무상 사고 등으로 출산한 자녀에게 부상·질병·장해·사망이 생기면 업무상 재해로 본다.\nㄷ X 건강손상자녀의 보험급여는 요양급여, 장해급여, 간병급여, 장례비, 직업재활급여다. 장례비가 들어 있다.\nㄹ X 건강손상자녀의 장해등급 판정은 18세 이후에 한다.","c":"상"},"공인노2025_34-59":{"w":"산재보험법 제65조의 순위: 근로자 사망 당시 생계를 같이 하던 배우자·자녀·부모·손자녀·조부모, 그다음 생계를 같이 하지 않던 배우자·자녀·부모·손자녀·조부모, 그다음 형제자매 순이다.\n선지 중에서는 생계를 같이 하던 자녀가 가장 앞선다.","c":"상"},"공인노2026_35-55":{"w":"산재보험법 제112조: 휴업급여를 받을 권리는 3년이다.\n장해급여, 유족급여, 장례비, 진폐보상연금을 받을 권리는 5년이다.","c":"상"},"공인노2026_35-57":{"w":"산재보험법 제64조 제1항의 자격 상실 사유는 사망, 배우자의 재혼(사실혼 포함), 친족관계 종료, 자녀·손자녀가 25세가 된 때, 형제자매가 19세가 된 때, 장애 해소, 국적 상실 후 외국 거주 등이다.\n자녀의 기준 나이는 20세가 아니라 25세다.","c":"상"},"공인노2026_35-60":{"w":"직장복귀지원금은 제75조의 직업재활급여다. 요양급여(제40조 제4항)에는 들어가지 않는다.\n간호·간병, 재활치료, 진찰·검사, 약제·진료재료·보조기 지급은 요양급여 범위다.","c":"상"},"공인노2026_35-61":{"w":"산재보험법 제91조의3 제2항: 진폐보상연금은 평균임금을 기준으로 별표 6에 따라 산정한 진폐장해연금과 기초연금을 합한 금액이고, 기초연금은 최저임금액의 100분의 60에 365를 곱한 금액이다.","c":"상"},"공인노2026_35-62":{"w":"시행령 별표 2: 분자는 전전 보험연도 7월부터 직전 보험연도 6월까지의 근로자 1명당 월평균 임금총액 합계, 분모는 3년 전 보험연도 7월부터 전전 보험연도 6월까지의 합계다.\nㄱ 7, ㄴ 6, ㄷ 3","c":"상"},"공인노2026_35-63":{"w":"산재보험법 제91조의14: 건강손상자녀에 대한 보험급여는 요양급여, 장해급여, 간병급여, 장례비, 직업재활급여다.\n휴업급여, 유족급여, 진폐보상연금, 상병보상연금은 해당하지 않는다.","c":"상"},"공인노2017_26-88":{"w":"출제 당시 산재보험법 시행령의 특수형태근로종사자 범위에는 보험설계사와 함께 새마을금고·신용협동조합 공제 모집인, 우체국보험 모집 전업자가 들어 있었고 농업협동조합 공제 모집인은 없었다.\n택배원, 대출 모집인, 신용카드회원 모집인, 전속 대리운전기사는 범위에 있었다.","c":"중"},"공인노2017_26-90":{"w":"산재보험법 시행령: 산업재해보상보험및예방심의위원회 위원의 임기는 3년이고 연임할 수 있다.\n② 보궐위원 임기는 전임자의 남은 기간이고, ③·④·⑤는 해촉 사유다.","c":"상"},"공인노2019_28-87":{"w":"퀵서비스 기사가 특수형태근로종사자가 되려면 본인이 직접 배송 노무를 제공해야 한다. 직원을 채용해 배송 업무를 하는 사람은 사업자이므로 범위에서 빠진다.\n학습지 교사, 보험설계사, 골프장 캐디, 신용카드회원 모집인은 범위에 있다.","c":"상"},"공인노2019_28-90":{"w":"산재보험법 시행령 제35조 제2항의 일상생활에 필요한 행위에 다섯 개 모두 있다. 일상생활 용품 구입, 학교·직업훈련기관에서 직업능력 개발향상 교육·훈련을 받는 행위, 선거권·국민투표권 행사, 보호 중인 아동·장애인을 보육·교육기관에 데려다주거나 데려오는 행위, 의료기관·보건소에서 질병 치료나 예방 목적의 진료를 받는 행위.","c":"상"},"공인노2022_31-86":{"w":"산재보험법 제8조 제1항의 심의 사항은 요양급여 산정 기준, 산재보험료율 결정, 기금 운용계획, 산업안전보건법에 따른 산업재해 '예방'계획 등이다.\n③ 산업재해 보상의 세부계획은 심의 사항에 없다.","c":"상"},"공인노2022_31-87":{"w":"산재보험법 시행령 제2조의 적용 제외는 공무원·군인 재해보상법 적용 사업, 선원법·어선원법·사립학교교직원연금법 적용 사업, 가구내 고용활동, 농업·임업(벌목업 제외)·어업·수렵업 중 법인이 아닌 자의 상시 5명 미만 사업 등이다.\n벌목업은 임업에서 빠져 있어 5명 미만이어도 산재보험이 적용된다.","c":"상"},"공인노2022_31-88":{"w":"ㄱ 과태료 제34조 유사명칭 사용 금지 위반은 제129조의 과태료 대상이다.\nㄴ, ㄷ 거짓으로 보험급여를 받거나 받도록 시키거나 도와준 자는 제127조에 따라 징역 또는 벌금에 처한다.","c":"상"},"공인노2025_34-58":{"w":"과태료 대상은 유사명칭 사용자와 진료계획을 정당한 사유 없이 내지 않은 자 2명이다.\n거짓 수급자와 이를 시킨 자, 보험급여 신청을 이유로 불이익 처우를 한 사업주는 징역 또는 벌금 대상이다.","c":"상"},"공인노2025_34-61":{"w":"산재보험법 시행령의 노무제공자 직종에 방문판매원이 있지만, 방문판매는 하지 않고 자가 소비만 하는 사람은 제외된다.\n신용카드회원 모집인, 어린이통학버스 운전자, 대여 제품 방문 점검원, 우체국보험 모집 전업자는 노무제공자다.","c":"상"},"공인노2026_35-54":{"w":"산재보험법 제129조: 제91조의21에 따른 플랫폼 운영자의 자료·정보 제공 요청에 따르지 않은 자는 300만원 이하의 과태료 대상이다.\n유사명칭 사용, 근로복지공단이 아닌 자에 대한 진료비 청구, 산재보험 의료기관 조사 거부는 200만원 이하, 진료계획 미제출은 100만원 이하의 과태료 대상이다.","c":"중"},"공인노2026_35-58":{"w":"산재보험법 시행령의 명단 공개 대상은 직전 연도부터 과거 3년간 부정수급 횟수 2회 이상이고 합계액 1억원 이상인 자, 또는 같은 기간 1회 부정수급액이 2억원 이상인 자다.\n③은 3년 내 1회 3억원이므로 해당한다. ①·②는 기간 기준이 다르고, ④·⑤는 '직전 연도부터 과거 3년' 요건과 금액 요건을 채우지 못한다.","c":"중"},"공인노2017_26-92":{"w":"출제 당시 국민연금법 제61조 제1항: 가입기간 10년 이상인 가입자(였던 자)에게 60세(특수직종근로자 55세)부터 노령연금을 지급한다.\n지급개시 연령은 부칙에 따라 출생연도별로 65세까지 단계적으로 늦춰진다.","c":"상"},"공인노2019_28-91":{"w":"출제 당시 국민연금법 제19조: 자녀 2명이면 12개월, 3명 이상이면 12개월에 2자녀 초과 1명마다 18개월을 더하고, 추가 산입 기간은 50개월을 넘을 수 없었다. 그래서 정답은 ②였다.\n2026년 1월 1일 시행 개정법은 첫째 자녀부터 12개월씩 인정하고 50개월 상한을 없앴다. 현행법으로는 맞는 선지가 없다.","c":"의심","old":1,"ow":"출제 당시 정답 ②(50, 12, 18). 2026.1.1 시행 개정으로 출산 크레딧은 첫째 자녀부터 12개월씩, 셋째부터는 1명당 18개월을 인정하고 50개월 상한이 없어져 지금 조문으로는 맞는 선지가 없다(국민연금법 제19조)."},"공인노2024_33-65":{"w":"국민연금법 제115조 제1항: 징수·환수 권리는 3년, 급여를 받거나 과오납금을 반환받을 권리는 5년이다(반환일시금은 10년).\n3 + 5 = 8","c":"상"},"공인노2024_33-67":{"w":"국민연금법 시행령 제64조: 사업장가입자 사용자에게는 납부 기한 후 20일 이내, 지역가입자에게는 3개월 이내, 제2차 납부의무자에게는 20일 이내에 독촉장을 발부한다.","c":"상"},"공인노2026_35-65":{"w":"국민연금법 제97조 제2항: 납부 기한 후 30일이 지난 날부터 매 1일마다 체납 보험료의 6천분의 1을 가산하고, 연체금 총액은 체납 보험료의 1천분의 50을 넘지 못한다.","c":"상"},"공인노2026_35-66":{"w":"① 국민연금법 제72조 제1항 제1호: 노령연금 수급권자가 사망하면 유족연금을 지급한다. 국적상실 기간 중 사망을 이유로 지급하지 않는 제72조 제2항은 제3호·제4호(보험료 납부 기간 요건)에만 적용된다.\n② 가입기간 10년 미만, ③ 장애등급 2급 이상이 아님, ④ 가입 대상 제외 기간 중 사망, ⑤ 체납기간 3년 이상이어서 모두 지급 대상이 아니다.","c":"상"},"공인노2026_35-67":{"w":"2026년 시행 개정 국민연금법 제51조 제1항: 기본연금액은 각 호 금액 합계에 1천분의 1천290을 곱하고, 가입기간이 20년을 넘으면 초과 1년마다 1천분의 50을 곱한 금액을 더한다.","c":"중"},"공인노2026_35-68":{"w":"2026년 시행 개정 국민연금법 제19조 제1항: 자녀가 2명 이하이면 1명마다 12개월, 3명 이상이면 첫째·둘째에 대한 24개월에 2자녀 초과 1명마다 18개월을 더한다.","c":"상"},"공인노2017_26-94":{"w":"국민건강보험법 제9조 제1항: 직장가입자인 근로자등이 그 사용관계가 끝난 날의 '다음 날'에 자격이 변동된다.\n①·②·④·⑤는 모두 그 날 변동된다.","c":"상"},"공인노2019_28-95":{"w":"국민건강보험법 제75조와 시행규칙: 직장가입자 중 휴직기간이 1개월 이상인 사람은 보험료를 경감받을 수 있다.\n65세 이상, 등록 장애인, 국가유공자 경감은 지역가입자에게 적용하는 사유다. 출산휴가는 경감 사유가 아니다.","c":"중"},"공인노2022_31-95":{"w":"국민건강보험법 제6조 제2항과 시행령 제9조의 직장가입자 제외자에 네 개 모두 있다. 고용 기간 1개월 미만 일용근로자, 월 소정근로시간 60시간 미만 단시간근로자, 군간부후보생, 보수를 받지 않는 선출직 공무원.","c":"상"},"공인노2024_33-69":{"w":"국민건강보험법 시행규칙의 연체금 미징수 사유에 네 개 모두 있다. 전쟁·사변으로 체납한 경우, 화재·폭설 등 재해로 체납한 경우, 사업장 폐업·도산으로 체납액을 징수할 수 없는 경우, 연체금이 공단 정관으로 정한 금액 이하인 경우.","c":"상"},"공인노2024_33-70":{"w":"ㄱ X 지역가입자가 사용자로 된 '날'에 변동된다.\nㄴ O\nㄷ O\nㄹ O 사용관계가 끝난 날의 다음 날","c":"상"},"공인노2024_33-71":{"w":"② 국민건강보험법 제19조: 공단의 해산은 법률로 정한다. 정관으로 정할 사항이 아니다.\n① 제15조 제1항, ③ 제15조 제2항, ④ 제18조, ⑤ 제16조 제1항","c":"상"},"공인노2024_33-73":{"w":"시행규칙의 피부양자 자격 상실 시기로 판단한다.\nㄱ X 국적을 잃은 날의 다음 날\nㄴ O 사망한 날의 다음 날\nㄷ O 직장가입자가 자격을 상실한 날\nㄹ X 본인 신고로 상실하면 신고한 날의 다음 날","c":"상"},"공인노2025_34-68":{"w":"제20조: 이사장 1명, 이사 14명, 감사 1명.\n시행령: 이사회 정기회의는 매년 2회.\n제89조: 건강보험분쟁조정위원회는 위원장 포함 60명 이내, 당연직위원 1명.\n들어가는 숫자는 14, 1, 2, 60, 1이고 20은 없다.","c":"상"},"공인노2025_34-69":{"w":"③ 시행령 제9조: 월 소정근로시간 60시간 미만인 시간제공무원만 제외되므로, 60시간 이상이면 직장가입자다.\n① 비상근 근로자, ② 현역병, ④ 1개월 미만 일용근로자, ⑤ 보수 없는 선출직 공무원은 제외된다.","c":"상"},"공인노2025_34-70":{"w":"국민건강보험법 시행령: 지역가입자의 재산보험료부과점수당 금액은 208.4원이다(2024년 이후 기준).","c":"중"},"공인노2025_34-71":{"w":"국민건강보험법 제52조 제2항 제1호: 일반건강검진 대상은 직장가입자, 세대주인 지역가입자, 20세 이상인 지역가입자, 20세 이상인 피부양자다.\n19세 피부양자는 대상이 아니다. 직장가입자는 나이와 관계없이 대상이다.","c":"상"},"공인노2025_34-72":{"w":"제9조 제1항: 지역가입자가 다른 세대로 전입한 '날'에 자격이 변동된다.\n① 사용관계가 끝난 날의 다음 날은 맞는 시기다.","c":"상"},"공인노2025_34-73":{"w":"국민건강보험법 제41조 제1항의 요양급여는 진찰·검사, 약제·치료재료 지급, 처치·수술 등 치료, 예방·재활, 입원, 간호, 이송이다.\n장제비는 제50조의 부가급여다.","c":"상"},"공인노2026_35-69":{"w":"제52조: 직장가입자(나이 무관), 세대주인 지역가입자, 20세 이상 지역가입자와 피부양자가 대상이다.\n20세 지역가입자 O, 19세 피부양자 X, 19세 직장가입자 O, 세대주 지역가입자 O\n대상은 3개.","c":"상"},"공인노2026_35-71":{"w":"시행령 제9조의 직장가입자 제외에 네 개 모두 있다. 군간부후보생, 소재지가 일정하지 않은 사업장의 근로자와 사용자, 근로자가 없거나 비상근 근로자만 고용한 사업장의 사업주.","c":"상"},"공인노2026_35-72":{"w":"국민건강보험법 제100조 제1항: 거짓 청구 금액이 1천500만원 이상이거나, 요양급여비용 총액 중 거짓 청구 비율이 100분의 20 이상이면 위반사실을 공표할 수 있다.","c":"상"},"공인노2026_35-74":{"w":"제10조 제1항: 직장가입자의 피부양자가 된 '날'에 자격을 잃는다.\n① 수급권자가 된 날, ② 국적을 잃은 날의 다음 날, ④ 국내에 거주하지 않게 된 날의 다음 날, ⑤ 적용 배제 신청을 한 날은 모두 맞다.","c":"상"},"공인노2017_26-97":{"w":"징수법 시행령의 기준보수는 사업의 폐업·도산 등으로 보수를 확인하기 곤란하거나, 사업장 이전 등으로 소재지를 파악하기 곤란한 경우에 쓴다.\n적용 단위는 시간급 근로자는 시간단위, 일급(일당) 근로자는 일단위, 월정액 근로자와 어느 쪽인지 명확하지 않은 근로자는 월단위다. 일당 근로자에게는 일단위 기준보수를 그대로 쓰고, 소정근로시간을 실제 근로시간으로 보아 계산하는 방식은 단시간 근로자의 시간단위 기준보수에 쓰는 방식이다.","c":"중"},"공인노2017_26-98":{"w":"징수법 제16조의7: 월별보험료는 다음 달 10일까지 납부한다.\n제16조의10: 사업주는 전년도 보수총액을 매년 3월 15일까지 근로복지공단에 신고한다.","c":"상"},"공인노2017_26-100":{"w":"③ 징수법 제10조: 공단이 보험관계를 소멸시키면 소멸을 결정·통지한 날의 다음 날에 소멸한다.\n① 하수급인은 하도급공사 착공일에 성립한다.\n② 근로자를 사용하지 않은 첫날부터 1년이 되는 날의 다음 날에 소멸한다.\n④ 공단 승인을 받은 날의 다음 날에 소멸한다.\n⑤ 일괄적용 사업은 처음 하는 사업이 시작된 날에 성립한다.","c":"상"},"공인노2019_28-97":{"w":"징수법 시행령의 보험사무대행기관 위임 범위는 개산·확정보험료 신고, 고용보험 피보험자격 관리, 보험관계 성립·소멸 신고, 보험관계 변경 신고, 근로자 고용·고용종료 신고 등 사업주가 해야 할 신고·관리 사무다.\n확정보험료 '부과'는 근로복지공단이 하는 처분이어서 위임 대상이 아니다.","c":"상"},"공인노2019_28-99":{"w":"징수법 시행령: 천재지변 등 특수한 사유로 인한 보험료 경감 비율은 100분의 30이다.\n자영업자의 실업급여 보험료율은 1천분의 20이다.","c":"중"},"공인노2022_31-96":{"w":"징수법 제18조: 근로복지공단은 보험료율이 바뀌면 월별보험료와 개산보험료를 조정하고, 증액된 월별보험료는 국민건강보험공단이, 증액된 개산보험료는 근로복지공단이 징수한다.","c":"상"},"공인노2022_31-98":{"w":"징수법 시행령 제12조: 고용안정·직업능력개발사업 보험료율은 150명 미만 1만분의 25, 150명 이상 우선지원대상기업 1만분의 45, 150명 이상 1천명 미만 1만분의 65, 1천명 이상과 국가·지방자치단체 사업 1만분의 85다.","c":"상"},"공인노2022_31-100":{"w":"징수법 제12조: 보험에 가입한 사업주는 이름, 사업 소재지 등이 변경되면 그 날부터 14일 이내에 근로복지공단에 신고한다.","c":"상"},"공인노2024_33-76":{"w":"ㄱ X 제13조 제2항: 근로자는 실업급여 보험료율의 2분의 1만 부담한다. 고용안정·직업능력개발사업 보험료는 사업주만 낸다.\nㄴ X 제16조의2: 보험료는 근로복지공단이 매월 부과하고 국민건강보험공단이 징수한다.\nㄷ X 산재보험료는 사업주에게서만 징수한다.\nㄹ X 재해예방활동 인정 취소는 고용노동부장관이 한다.","c":"상"},"공인노2024_33-77":{"w":"징수법 제27조의2의 납부기한 전 징수 사유는 국세 체납처분, 지방세·공과금 체납처분, 강제집행, 어음교환소 거래정지처분, 법인 해산 등이다.\n법인 합병은 사유가 아니다. 합병 후 법인이 의무를 그대로 승계하기 때문이다.","c":"상"},"공인노2024_33-79":{"w":"징수법상 거짓이나 부정한 방법으로 인가를 받아 인가가 취소된 보험사무대행기관은 취소된 날부터 1년 동안 다시 인가를 받을 수 없다.","c":"중"},"공인노2024_33-80":{"w":"시행령 제12조 고용안정·직업능력개발사업 보험료율로 맞춘다.\nㄱ 120명(150명 미만) → 1만분의 25(b)\nㄴ 1,000명 → 1만분의 85(d)\nㄷ 국가·지방자치단체 직접 사업 → 1만분의 85(d)\nㄱ-b, ㄷ-d가 들어 있는 ②가 맞다.","c":"상"},"공인노2025_34-75":{"w":"시행령 제12조: 150명 이상 우선지원대상기업 1만분의 45, 국가·지방자치단체가 직접 하는 사업 1만분의 85.","c":"상"},"공인노2026_35-78":{"w":"징수법 제27조의2 제1항의 납부기한 전 징수 사유에 네 개 모두 있다. 국세 체납처분, 지방세·공과금 체납처분, 강제집행, 어음교환소 거래정지처분.","c":"상"},"공인노2026_35-79":{"w":"징수법 시행령의 과오납금 충당 순위는 체납처분비가 가장 앞이고, 그다음 월별보험료·확정보험료·연체금 등의 순이다.","c":"중"},"공인노2026_35-80":{"w":"징수법 시행령 제12조: 150명 미만 사업의 고용안정·직업능력개발사업 보험료율은 1만분의 25, 실업급여 보험료율은 1천분의 18이다.","c":"상"},"공인노2022_31-90":{"w":"산재보험법 시행령 제27조 제2항: 근로자가 사업주의 구체적인 지시를 위반한 행위, 근로자의 사적 행위, 업무를 벗어난 행위로 생긴 사고는 업무상 사고로 보지 않는다.\n①은 법 제37조 제1항 제1호 가목, ③은 나목, ④는 라목, ⑤는 마목의 업무상 사고다.","c":"상"}};
